insert into public.questions (id, cat, status, q, options, correct, expl, ref, src) values
($q$s01$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which companion of the Prophet ﷺ is mentioned by name in the Quran?","roman":"Kis sahabi ka naam Quran mein aaya hai?","ur":"کس صحابی کا نام قرآن میں آیا ہے؟"}$q$::jsonb,$q$[{"en":"Zaid ibn Harithah (RA)","roman":"Zaid ibn Harithah (RA)","ur":"زید بن حارثہ رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Umar ibn al-Khattab (RA)","roman":"Umar ibn al-Khattab (RA)","ur":"عمر بن خطاب رضی اللہ عنہ"},{"en":"Bilal ibn Rabah (RA)","roman":"Bilal ibn Rabah (RA)","ur":"بلال بن رباح رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Surah Al-Ahzab 33:37 names Zaid (RA). He is the only companion mentioned by name in the Quran.","roman":"Surah Al-Ahzab 33:37 mein Hazrat Zaid (RA) ka naam hai. Woh wahid sahabi hain jinka naam Quran mein aaya.","ur":"سورۃ الاحزاب 33:37 میں حضرت زید رضی اللہ عنہ کا نام ہے۔ وہ واحد صحابی ہیں جن کا نام قرآن میں آیا۔"}$q$::jsonb,$q$Quran 33:37$q$,$q$quran$q$),
($q$s02$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which woman is mentioned by name in the Quran?","roman":"Kis khatoon ka naam Quran mein aaya hai?","ur":"کس خاتون کا نام قرآن میں آیا ہے؟"}$q$::jsonb,$q$[{"en":"Maryam (AS)","roman":"Maryam (AS)","ur":"مریم علیہا السلام"},{"en":"Khadijah (RA)","roman":"Khadijah (RA)","ur":"خدیجہ رضی اللہ عنہا"},{"en":"Hajar (AS)","roman":"Hajar (AS)","ur":"ہاجرہ علیہا السلام"},{"en":"Aasiyah","roman":"Aasiyah","ur":"آسیہ"}]$q$::jsonb,0,$q${"en":"Maryam, the mother of Isa (AS), is the only woman named in the Quran, and a surah is named after her.","roman":"Hazrat Maryam (AS), Hazrat Isa (AS) ki walida, wahid khatoon hain jinka naam Quran mein hai, aur un ke naam par surah bhi hai.","ur":"حضرت مریم علیہا السلام، حضرت عیسیٰ علیہ السلام کی والدہ، واحد خاتون ہیں جن کا نام قرآن میں ہے، اور ان کے نام پر سورت بھی ہے۔"}$q$::jsonb,$q$Quran 19:16, 66:12$q$,$q$quran$q$),
($q$s03$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Which were the first ayat revealed to the Prophet ﷺ?","roman":"Nabi ﷺ par sab se pehle kaunsi ayat nazil huin?","ur":"نبی ﷺ پر سب سے پہلے کون سی آیات نازل ہوئیں؟"}$q$::jsonb,$q$[{"en":"The opening ayat of Surah Al-Alaq","roman":"The opening ayat of Surah Al-Alaq","ur":"سورۃ العلق کی ابتدائی آیات"},{"en":"Surah Al-Fatihah","roman":"Surah Al-Fatihah","ur":"سورۃ الفاتحہ"},{"en":"Ayat al-Kursi","roman":"Ayat al-Kursi","ur":"آیت الکرسی"},{"en":"Surah Al-Ikhlas","roman":"Surah Al-Ikhlas","ur":"سورۃ الاخلاص"}]$q$::jsonb,0,$q${"en":"\"Read in the name of your Lord…\" (96:1–5) was revealed first, in the cave of Hira (Sahih al-Bukhari 3).","roman":"\"Iqra bismi Rabbik…\" (96:1–5) sab se pehle Ghar-e-Hira mein nazil hui (Sahih Bukhari 3).","ur":"\"اقرأ باسم ربک…\" (96:1–5) سب سے پہلے غارِ حرا میں نازل ہوئیں (صحیح بخاری 3)۔"}$q$::jsonb,$q$Quran 96:1–5$q$,$q$quran$q$),
($q$s04$q$,$q$seerah$q$,$q$published$q$,$q${"en":"In which cave did the first revelation come?","roman":"Pehli wahi kis ghaar mein aayi?","ur":"پہلی وحی کس غار میں آئی؟"}$q$::jsonb,$q$[{"en":"Hira","roman":"Hira","ur":"حرا"},{"en":"Thawr","roman":"Thawr","ur":"ثور"},{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Quba","roman":"Quba","ur":"قبا"}]$q$::jsonb,0,$q${"en":"The Prophet ﷺ used to worship in the cave of Hira, where Jibreel (AS) brought the first revelation.","roman":"Nabi ﷺ Ghar-e-Hira mein ibadat karte the, wahin Jibreel (AS) pehli wahi laaye.","ur":"نبی ﷺ غارِ حرا میں عبادت کرتے تھے، وہیں جبریل علیہ السلام پہلی وحی لائے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3$q$,$q$seerah$q$),
($q$s05$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Who was with the Prophet ﷺ in the cave during the Hijrah?","roman":"Hijrat ke dauran ghaar mein Nabi ﷺ ke saath kaun tha?","ur":"ہجرت کے دوران غار میں نبی ﷺ کے ساتھ کون تھا؟"}$q$::jsonb,$q$[{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Quran 9:40 refers to \"the second of two, when they were in the cave\"; the companion was Abu Bakr (RA), in the cave of Thawr.","roman":"Quran 9:40 mein \"do mein se doosre\" ka zikr hai; yeh Hazrat Abu Bakr (RA) the, Ghar-e-Saur mein.","ur":"قرآن 9:40 میں \"دو میں سے دوسرے\" کا ذکر ہے؛ یہ حضرت ابو بکر رضی اللہ عنہ تھے، غارِ ثور میں۔"}$q$::jsonb,$q$Quran 9:40$q$,$q$quran$q$),
($q$s06$q$,$q$seerah$q$,$q$published$q$,$q${"en":"In which cave did the Prophet ﷺ hide during the Hijrah?","roman":"Hijrat ke waqt Nabi ﷺ kis ghaar mein chhupe?","ur":"ہجرت کے وقت نبی ﷺ کس غار میں چھپے؟"}$q$::jsonb,$q$[{"en":"Thawr","roman":"Thawr","ur":"ثور"},{"en":"Hira","roman":"Hira","ur":"حرا"},{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Badr","roman":"Badr","ur":"بدر"}]$q$::jsonb,0,$q${"en":"The Prophet ﷺ and Abu Bakr (RA) stayed three nights in the cave of Thawr before travelling to Madinah.","roman":"Nabi ﷺ aur Hazrat Abu Bakr (RA) Madinah jane se pehle teen raat Ghar-e-Saur mein rahe.","ur":"نبی ﷺ اور حضرت ابو بکر رضی اللہ عنہ مدینہ جانے سے پہلے تین راتیں غارِ ثور میں رہے۔"}$q$::jsonb,$q$Ibn Hisham; Ar-Raheeq al-Makhtum$q$,$q$seerah$q$),
($q$s07$q$,$q$seerah$q$,$q$published$q$,$q${"en":"What was the name of the Prophet's ﷺ mother?","roman":"Nabi ﷺ ki walida ka naam kya tha?","ur":"نبی ﷺ کی والدہ کا نام کیا تھا؟"}$q$::jsonb,$q$[{"en":"Aminah bint Wahb","roman":"Aminah bint Wahb","ur":"آمنہ بنت وہب"},{"en":"Halimah as-Sa'diyyah","roman":"Halimah as-Sa'diyyah","ur":"حلیمہ سعدیہ"},{"en":"Fatimah bint Asad","roman":"Fatimah bint Asad","ur":"فاطمہ بنت اسد"},{"en":"Barakah (Umm Ayman)","roman":"Barakah (Umm Ayman)","ur":"برکہ (ام ایمن)"}]$q$::jsonb,0,$q${"en":"His mother was Aminah bint Wahb; she passed away when he was about six years old.","roman":"Aap ﷺ ki walida Aminah bint Wahb thin; jab aap taqreeban chhe saal ke the to un ka inteqal hua.","ur":"آپ ﷺ کی والدہ آمنہ بنت وہب تھیں؛ جب آپ تقریباً چھ سال کے تھے تو ان کا انتقال ہوا۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s08$q$,$q$seerah$q$,$q$published$q$,$q${"en":"What was the name of the Prophet's ﷺ father?","roman":"Nabi ﷺ ke walid ka naam kya tha?","ur":"نبی ﷺ کے والد کا نام کیا تھا؟"}$q$::jsonb,$q$[{"en":"Abdullah ibn Abdul-Muttalib","roman":"Abdullah ibn Abdul-Muttalib","ur":"عبداللہ بن عبدالمطلب"},{"en":"Abu Talib","roman":"Abu Talib","ur":"ابو طالب"},{"en":"Abbas","roman":"Abbas","ur":"عباس"},{"en":"Hamzah","roman":"Hamzah","ur":"حمزہ"}]$q$::jsonb,0,$q${"en":"His father Abdullah passed away before the Prophet ﷺ was born.","roman":"Aap ﷺ ke walid Abdullah aap ki wiladat se pehle wafat pa gaye the.","ur":"آپ ﷺ کے والد عبداللہ آپ کی ولادت سے پہلے وفات پا گئے تھے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s09$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Who was the Prophet's ﷺ wet nurse in the desert?","roman":"Dehaat mein Nabi ﷺ ko doodh pilane wali kaun thin?","ur":"دیہات میں نبی ﷺ کو دودھ پلانے والی کون تھیں؟"}$q$::jsonb,$q$[{"en":"Halimah as-Sa'diyyah","roman":"Halimah as-Sa'diyyah","ur":"حلیمہ سعدیہ"},{"en":"Aminah","roman":"Aminah","ur":"آمنہ"},{"en":"Khadijah","roman":"Khadijah","ur":"خدیجہ"},{"en":"Sumayyah","roman":"Sumayyah","ur":"سمیہ"}]$q$::jsonb,0,$q${"en":"Halimah of the Banu Sa'd tribe nursed him in the desert during his early childhood.","roman":"Banu Saad ki Hazrat Halimah ne bachpan mein aap ﷺ ko dehaat mein doodh pilaya.","ur":"بنو سعد کی حضرت حلیمہ نے بچپن میں آپ ﷺ کو دیہات میں دودھ پلایا۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s10$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Which uncle raised the Prophet ﷺ after his grandfather died?","roman":"Dada ki wafat ke baad kis chacha ne Nabi ﷺ ki parwarish ki?","ur":"دادا کی وفات کے بعد کس چچا نے نبی ﷺ کی پرورش کی؟"}$q$::jsonb,$q$[{"en":"Abu Talib","roman":"Abu Talib","ur":"ابو طالب"},{"en":"Abu Lahab","roman":"Abu Lahab","ur":"ابو لہب"},{"en":"Abbas","roman":"Abbas","ur":"عباس"},{"en":"Hamzah","roman":"Hamzah","ur":"حمزہ"}]$q$::jsonb,0,$q${"en":"After Abdul-Muttalib died, his uncle Abu Talib looked after him and later protected him in Makkah.","roman":"Abdul-Muttalib ki wafat ke baad chacha Abu Talib ne parwarish ki aur baad mein Makkah mein hifazat bhi ki.","ur":"عبدالمطلب کی وفات کے بعد چچا ابو طالب نے پرورش کی اور بعد میں مکہ میں حفاظت بھی کی۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s11$q$,$q$seerah$q$,$q$published$q$,$q${"en":"The Prophet ﷺ was born in which well-known year?","roman":"Nabi ﷺ kis mashhoor saal mein paida hue?","ur":"نبی ﷺ کس مشہور سال میں پیدا ہوئے؟"}$q$::jsonb,$q$[{"en":"The Year of the Elephant","roman":"The Year of the Elephant","ur":"عام الفیل"},{"en":"The Year of Sorrow","roman":"The Year of Sorrow","ur":"عام الحزن"},{"en":"The year of Hijrah","roman":"The year of Hijrah","ur":"ہجرت کا سال"},{"en":"The year of Badr","roman":"The year of Badr","ur":"بدر کا سال"}]$q$::jsonb,0,$q${"en":"He was born in the Year of the Elephant, when Abrahah's army marched on the Ka'bah (Surah Al-Fil).","roman":"Aap ﷺ Aam-ul-Feel mein paida hue, jab Abraha ki fauj ne Kaaba par hamla kiya (Surah Al-Feel).","ur":"آپ ﷺ عام الفیل میں پیدا ہوئے، جب ابرہہ کی فوج نے کعبہ پر حملہ کیا (سورۃ الفیل)۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s12$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the first wife of the Prophet ﷺ?","roman":"Nabi ﷺ ki pehli zauja kaun thin?","ur":"نبی ﷺ کی پہلی زوجہ کون تھیں؟"}$q$::jsonb,$q$[{"en":"Khadijah bint Khuwaylid (RA)","roman":"Khadijah bint Khuwaylid (RA)","ur":"خدیجہ بنت خویلد رضی اللہ عنہا"},{"en":"Aishah (RA)","roman":"Aishah (RA)","ur":"عائشہ رضی اللہ عنہا"},{"en":"Sawdah (RA)","roman":"Sawdah (RA)","ur":"سودہ رضی اللہ عنہا"},{"en":"Hafsah (RA)","roman":"Hafsah (RA)","ur":"حفصہ رضی اللہ عنہا"}]$q$::jsonb,0,$q${"en":"Khadijah (RA) married him before prophethood and was the first person to believe in his message.","roman":"Hazrat Khadijah (RA) ne nabuwwat se pehle nikah kiya aur sab se pehle aap ﷺ par iman laayin.","ur":"حضرت خدیجہ رضی اللہ عنہا نے نبوت سے پہلے نکاح کیا اور سب سے پہلے آپ ﷺ پر ایمان لائیں۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s13$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who is widely recognised as the first martyr of Islam?","roman":"Islam ki pehli shaheed kise mana jata hai?","ur":"اسلام کی پہلی شہید کسے مانا جاتا ہے؟"}$q$::jsonb,$q$[{"en":"Sumayyah bint Khayyat (RA)","roman":"Sumayyah bint Khayyat (RA)","ur":"سمیہ بنت خیاط رضی اللہ عنہا"},{"en":"Khadijah (RA)","roman":"Khadijah (RA)","ur":"خدیجہ رضی اللہ عنہا"},{"en":"Hamzah (RA)","roman":"Hamzah (RA)","ur":"حمزہ رضی اللہ عنہ"},{"en":"Yasir (RA)","roman":"Yasir (RA)","ur":"یاسر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Sumayyah (RA), mother of Ammar ibn Yasir, was killed in Makkah for refusing to give up Islam.","roman":"Hazrat Ammar bin Yasir ki walida Hazrat Sumayyah (RA) ko Islam na chhorne par Makkah mein shaheed kiya gaya.","ur":"حضرت عمار بن یاسر کی والدہ حضرت سمیہ رضی اللہ عنہا کو اسلام نہ چھوڑنے پر مکہ میں شہید کیا گیا۔"}$q$::jsonb,$q$Ibn Hisham; Ar-Raheeq al-Makhtum$q$,$q$seerah$q$),
($q$s14$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the first muezzin of Islam?","roman":"Islam ke pehle muazzin kaun the?","ur":"اسلام کے پہلے مؤذن کون تھے؟"}$q$::jsonb,$q$[{"en":"Bilal ibn Rabah (RA)","roman":"Bilal ibn Rabah (RA)","ur":"بلال بن رباح رضی اللہ عنہ"},{"en":"Abdullah ibn Zaid (RA)","roman":"Abdullah ibn Zaid (RA)","ur":"عبداللہ بن زید رضی اللہ عنہ"},{"en":"Ammar ibn Yasir (RA)","roman":"Ammar ibn Yasir (RA)","ur":"عمار بن یاسر رضی اللہ عنہ"},{"en":"Salman al-Farisi (RA)","roman":"Salman al-Farisi (RA)","ur":"سلمان فارسی رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"The Prophet ﷺ asked Bilal (RA) to call the adhan because of his strong, beautiful voice.","roman":"Nabi ﷺ ne Hazrat Bilal (RA) ko unki buland aur khoobsurat awaz ki wajah se azaan dene ko kaha.","ur":"نبی ﷺ نے حضرت بلال رضی اللہ عنہ کو ان کی بلند اور خوبصورت آواز کی وجہ سے اذان دینے کو کہا۔"}$q$::jsonb,$q$Sunan Abi Dawud 499$q$,$q$seerah$q$),
($q$s15$q$,$q$history$q$,$q$published$q$,$q${"en":"What was the first major battle of Islam?","roman":"Islam ki pehli bari jung kaunsi thi?","ur":"اسلام کی پہلی بڑی جنگ کون سی تھی؟"}$q$::jsonb,$q$[{"en":"Badr","roman":"Badr","ur":"بدر"},{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Khandaq","roman":"Khandaq","ur":"خندق"},{"en":"Hunayn","roman":"Hunayn","ur":"حنین"}]$q$::jsonb,0,$q${"en":"The Battle of Badr took place in Ramadan, 2 AH. The Quran mentions Badr by name in 3:123.","roman":"Jung-e-Badr Ramadan 2 Hijri mein hui. Quran 3:123 mein Badr ka naam aaya hai.","ur":"جنگِ بدر رمضان 2 ہجری میں ہوئی۔ قرآن 3:123 میں بدر کا نام آیا ہے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s16$q$,$q$history$q$,$q$published$q$,$q${"en":"Roughly how many Muslims fought at Badr?","roman":"Badr mein taqreeban kitne Musalman lare?","ur":"بدر میں تقریباً کتنے مسلمان لڑے؟"}$q$::jsonb,$q$[{"en":"About 313","roman":"About 313","ur":"تقریباً 313"},{"en":"About 700","roman":"About 700","ur":"تقریباً 700"},{"en":"About 1,000","roman":"About 1,000","ur":"تقریباً 1000"},{"en":"About 3,000","roman":"About 3,000","ur":"تقریباً 3000"}]$q$::jsonb,0,$q${"en":"Reports put the number at a little over 310, commonly given as 313.","roman":"Riwayat ke mutabiq tadaad 310 se kuch zyada thi, aam tor par 313 batai jati hai.","ur":"روایات کے مطابق تعداد 310 سے کچھ زیادہ تھی، عام طور پر 313 بتائی جاتی ہے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3957$q$,$q$seerah$q$),
($q$s17$q$,$q$history$q$,$q$published$q$,$q${"en":"In which battle did the archers leave their positions on the hill?","roman":"Kis jung mein teer andaz pahari par apni jagah chhor gaye?","ur":"کس جنگ میں تیر انداز پہاڑی پر اپنی جگہ چھوڑ گئے؟"}$q$::jsonb,$q$[{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Badr","roman":"Badr","ur":"بدر"},{"en":"Khandaq","roman":"Khandaq","ur":"خندق"},{"en":"Tabuk","roman":"Tabuk","ur":"تبوک"}]$q$::jsonb,0,$q${"en":"At Uhud (3 AH) some archers left the hill, which let the enemy attack from behind.","roman":"Uhud (3 Hijri) mein kuch teer andaz pahari chhor gaye, jis se dushman ne peeche se hamla kiya.","ur":"احد (3 ہجری) میں کچھ تیر انداز پہاڑی چھوڑ گئے، جس سے دشمن نے پیچھے سے حملہ کیا۔"}$q$::jsonb,$q$Quran 3:152; Sahih al-Bukhari 3039$q$,$q$seerah$q$),
($q$s18$q$,$q$history$q$,$q$published$q$,$q${"en":"Which companion suggested digging the trench at the Battle of Khandaq?","roman":"Jung-e-Khandaq mein khandaq khodne ka mashwara kis sahabi ne diya?","ur":"جنگِ خندق میں خندق کھودنے کا مشورہ کس صحابی نے دیا؟"}$q$::jsonb,$q$[{"en":"Salman al-Farisi (RA)","roman":"Salman al-Farisi (RA)","ur":"سلمان فارسی رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Khalid ibn al-Walid (RA)","roman":"Khalid ibn al-Walid (RA)","ur":"خالد بن ولید رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Salman al-Farisi (RA) shared the Persian method of defending with a trench.","roman":"Hazrat Salman Farsi (RA) ne Iran ka khandaq se difa ka tareeqa bataya.","ur":"حضرت سلمان فارسی رضی اللہ عنہ نے ایران کا خندق سے دفاع کا طریقہ بتایا۔"}$q$::jsonb,$q$Ibn Hisham; Ar-Raheeq al-Makhtum$q$,$q$seerah$q$),
($q$s19$q$,$q$history$q$,$q$published$q$,$q${"en":"Which treaty did the Quran call a \"clear victory\"?","roman":"Quran ne kis sulah ko \"fath-e-mubeen\" kaha?","ur":"قرآن نے کس صلح کو \"فتحِ مبین\" کہا؟"}$q$::jsonb,$q$[{"en":"The Treaty of Hudaybiyyah","roman":"The Treaty of Hudaybiyyah","ur":"صلح حدیبیہ"},{"en":"The Pledge of Aqabah","roman":"The Pledge of Aqabah","ur":"بیعتِ عقبہ"},{"en":"The Constitution of Madinah","roman":"The Constitution of Madinah","ur":"میثاقِ مدینہ"},{"en":"The Treaty of Najran","roman":"The Treaty of Najran","ur":"معاہدۂ نجران"}]$q$::jsonb,0,$q${"en":"Surah Al-Fath was revealed after the Treaty of Hudaybiyyah (6 AH) and calls it a clear victory.","roman":"Surah Al-Fath sulah Hudaibiyah (6 Hijri) ke baad nazil hui aur isay fath-e-mubeen kaha.","ur":"سورۃ الفتح صلح حدیبیہ (6 ہجری) کے بعد نازل ہوئی اور اسے فتحِ مبین کہا۔"}$q$::jsonb,$q$Quran 48:1, 48:18$q$,$q$quran$q$),
($q$s20$q$,$q$history$q$,$q$published$q$,$q${"en":"In which year after Hijrah was Makkah conquered?","roman":"Fath-e-Makkah Hijrat ke kis saal hui?","ur":"فتحِ مکہ ہجرت کے کس سال ہوئی؟"}$q$::jsonb,$q$[{"en":"8 AH","roman":"8 AH","ur":"8 ہجری"},{"en":"2 AH","roman":"2 AH","ur":"2 ہجری"},{"en":"5 AH","roman":"5 AH","ur":"5 ہجری"},{"en":"10 AH","roman":"10 AH","ur":"10 ہجری"}]$q$::jsonb,0,$q${"en":"Makkah was conquered in Ramadan, 8 AH, largely without fighting.","roman":"Makkah Ramadan 8 Hijri mein taqreeban baghair jung ke fath hua.","ur":"مکہ رمضان 8 ہجری میں تقریباً بغیر جنگ کے فتح ہوا۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s21$q$,$q$history$q$,$q$published$q$,$q${"en":"In which year did the Prophet ﷺ perform the Farewell Hajj?","roman":"Nabi ﷺ ne Hajjat-ul-Wida kis saal ada kiya?","ur":"نبی ﷺ نے حجۃ الوداع کس سال ادا کیا؟"}$q$::jsonb,$q$[{"en":"10 AH","roman":"10 AH","ur":"10 ہجری"},{"en":"8 AH","roman":"8 AH","ur":"8 ہجری"},{"en":"6 AH","roman":"6 AH","ur":"6 ہجری"},{"en":"9 AH","roman":"9 AH","ur":"9 ہجری"}]$q$::jsonb,0,$q${"en":"The Farewell Hajj was in 10 AH, a few months before the Prophet ﷺ passed away.","roman":"Hajjat-ul-Wida 10 Hijri mein hua, aap ﷺ ki wafat se kuch mahine pehle.","ur":"حجۃ الوداع 10 ہجری میں ہوا، آپ ﷺ کی وفات سے کچھ مہینے پہلے۔"}$q$::jsonb,$q$Sahih Muslim 1218$q$,$q$seerah$q$),
($q$s22$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Which was the first masjid built by the Prophet ﷺ after the Hijrah?","roman":"Hijrat ke baad Nabi ﷺ ne sab se pehle kaunsi masjid banai?","ur":"ہجرت کے بعد نبی ﷺ نے سب سے پہلے کون سی مسجد بنائی؟"}$q$::jsonb,$q$[{"en":"Masjid Quba","roman":"Masjid Quba","ur":"مسجدِ قبا"},{"en":"Masjid an-Nabawi","roman":"Masjid an-Nabawi","ur":"مسجدِ نبوی"},{"en":"Masjid al-Haram","roman":"Masjid al-Haram","ur":"مسجدِ حرام"},{"en":"Masjid al-Qiblatayn","roman":"Masjid al-Qiblatayn","ur":"مسجدِ قبلتین"}]$q$::jsonb,0,$q${"en":"On reaching Quba near Madinah he founded Masjid Quba; Quran 9:108 praises a masjid founded on taqwa.","roman":"Madinah ke qareeb Quba pahunch kar aap ﷺ ne Masjid Quba ki buniyad rakhi; Quran 9:108 mein taqwa par bani masjid ki tareef hai.","ur":"مدینہ کے قریب قبا پہنچ کر آپ ﷺ نے مسجدِ قبا کی بنیاد رکھی؛ قرآن 9:108 میں تقویٰ پر بنی مسجد کی تعریف ہے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3906; Ibn Hisham$q$,$q$seerah$q$),
($q$s23$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Towards which place was the qiblah changed?","roman":"Qibla kis taraf badla gaya?","ur":"قبلہ کس طرف بدلا گیا؟"}$q$::jsonb,$q$[{"en":"The Ka'bah in Makkah","roman":"The Ka'bah in Makkah","ur":"مکہ میں کعبہ"},{"en":"Bayt al-Maqdis","roman":"Bayt al-Maqdis","ur":"بیت المقدس"},{"en":"Masjid an-Nabawi","roman":"Masjid an-Nabawi","ur":"مسجدِ نبوی"},{"en":"Mount Sinai","roman":"Mount Sinai","ur":"کوہِ طور"}]$q$::jsonb,0,$q${"en":"Quran 2:144 commanded turning towards Al-Masjid al-Haram, changing the qiblah from Bayt al-Maqdis.","roman":"Quran 2:144 mein Masjid-e-Haram ki taraf rukh karne ka hukm aaya, Bait-ul-Maqdis se qibla badal gaya.","ur":"قرآن 2:144 میں مسجدِ حرام کی طرف رخ کرنے کا حکم آیا، بیت المقدس سے قبلہ بدل گیا۔"}$q$::jsonb,$q$Quran 2:144$q$,$q$quran$q$),
($q$s24$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Which surah begins with the Night Journey (Isra)?","roman":"Kaunsi surah Isra (raat ke safar) ke zikr se shuru hoti hai?","ur":"کون سی سورت اسراء (رات کے سفر) کے ذکر سے شروع ہوتی ہے؟"}$q$::jsonb,$q$[{"en":"Al-Isra","roman":"Al-Isra","ur":"الاسراء"},{"en":"An-Najm","roman":"An-Najm","ur":"النجم"},{"en":"Al-Kahf","roman":"Al-Kahf","ur":"الکہف"},{"en":"Al-Qadr","roman":"Al-Qadr","ur":"القدر"}]$q$::jsonb,0,$q${"en":"Surah Al-Isra 17:1 describes the journey from Al-Masjid al-Haram to Al-Masjid al-Aqsa by night.","roman":"Surah Al-Isra 17:1 mein Masjid-e-Haram se Masjid-e-Aqsa tak raat ke safar ka zikr hai.","ur":"سورۃ الاسراء 17:1 میں مسجدِ حرام سے مسجدِ اقصیٰ تک رات کے سفر کا ذکر ہے۔"}$q$::jsonb,$q$Quran 17:1$q$,$q$quran$q$),
($q$s25$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the first caliph after the Prophet ﷺ?","roman":"Nabi ﷺ ke baad pehle khalifa kaun the?","ur":"نبی ﷺ کے بعد پہلے خلیفہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Abu Bakr as-Siddiq (RA)","roman":"Abu Bakr as-Siddiq (RA)","ur":"ابو بکر صدیق رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Abu Bakr (RA) was chosen as the first caliph in 11 AH.","roman":"Hazrat Abu Bakr (RA) 11 Hijri mein pehle khalifa chune gaye.","ur":"حضرت ابو بکر رضی اللہ عنہ 11 ہجری میں پہلے خلیفہ چنے گئے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s26$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the second caliph?","roman":"Doosre khalifa kaun the?","ur":"دوسرے خلیفہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Umar ibn al-Khattab (RA)","roman":"Umar ibn al-Khattab (RA)","ur":"عمر بن خطاب رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Umar (RA) became caliph in 13 AH after Abu Bakr (RA).","roman":"Hazrat Umar (RA) 13 Hijri mein Hazrat Abu Bakr (RA) ke baad khalifa bane.","ur":"حضرت عمر رضی اللہ عنہ 13 ہجری میں حضرت ابو بکر رضی اللہ عنہ کے بعد خلیفہ بنے۔"}$q$::jsonb,$q$Tarikh al-Tabari$q$,$q$seerah$q$),
($q$s27$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the third caliph?","roman":"Teesre khalifa kaun the?","ur":"تیسرے خلیفہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Uthman ibn Affan (RA)","roman":"Uthman ibn Affan (RA)","ur":"عثمان بن عفان رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Talhah (RA)","roman":"Talhah (RA)","ur":"طلحہ رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Uthman (RA) became caliph in 24 AH.","roman":"Hazrat Usman (RA) 24 Hijri mein khalifa bane.","ur":"حضرت عثمان رضی اللہ عنہ 24 ہجری میں خلیفہ بنے۔"}$q$::jsonb,$q$Tarikh al-Tabari$q$,$q$seerah$q$),
($q$s28$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the fourth caliph?","roman":"Chauthe khalifa kaun the?","ur":"چوتھے خلیفہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Ali ibn Abi Talib (RA)","roman":"Ali ibn Abi Talib (RA)","ur":"علی بن ابی طالب رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Hasan (RA)","roman":"Hasan (RA)","ur":"حسن رضی اللہ عنہ"},{"en":"Zubair (RA)","roman":"Zubair (RA)","ur":"زبیر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ali (RA) became caliph in 35 AH.","roman":"Hazrat Ali (RA) 35 Hijri mein khalifa bane.","ur":"حضرت علی رضی اللہ عنہ 35 ہجری میں خلیفہ بنے۔"}$q$::jsonb,$q$Tarikh al-Tabari$q$,$q$seerah$q$),
($q$s29$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which companion was called Dhun-Nurayn (possessor of two lights)?","roman":"Kis sahabi ko Zun-Nurain (do noor wale) kaha jata hai?","ur":"کس صحابی کو ذوالنورین (دو نور والے) کہا جاتا ہے؟"}$q$::jsonb,$q$[{"en":"Uthman ibn Affan (RA)","roman":"Uthman ibn Affan (RA)","ur":"عثمان بن عفان رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Uthman (RA) married two daughters of the Prophet ﷺ, Ruqayyah and then Umm Kulthum (RA).","roman":"Hazrat Usman (RA) ke nikah mein Nabi ﷺ ki do sahibzadiyan aayin: Ruqayyah aur phir Umm Kulsoom (RA).","ur":"حضرت عثمان رضی اللہ عنہ کے نکاح میں نبی ﷺ کی دو صاحبزادیاں آئیں: رقیہ اور پھر ام کلثوم رضی اللہ عنہما۔"}$q$::jsonb,$q$Established title$q$,$q$seerah$q$),
($q$s30$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which companion is known as As-Siddiq?","roman":"Kis sahabi ka laqab Siddiq hai?","ur":"کس صحابی کا لقب صدیق ہے؟"}$q$::jsonb,$q$[{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Abu Hurairah (RA)","roman":"Abu Hurairah (RA)","ur":"ابو ہریرہ رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Abu Bakr (RA) was called As-Siddiq for immediately affirming the Prophet ﷺ, including the Night Journey.","roman":"Hazrat Abu Bakr (RA) ne foran Nabi ﷺ ki tasdeeq ki, Isra ke waqiye ki bhi, is liye Siddiq kehlaye.","ur":"حضرت ابو بکر رضی اللہ عنہ نے فوراً نبی ﷺ کی تصدیق کی، اسراء کے واقعے کی بھی، اس لیے صدیق کہلائے۔"}$q$::jsonb,$q$Established title$q$,$q$seerah$q$),
($q$s31$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which companion is known as Al-Faruq?","roman":"Kis sahabi ka laqab Farooq hai?","ur":"کس صحابی کا لقب فاروق ہے؟"}$q$::jsonb,$q$[{"en":"Umar ibn al-Khattab (RA)","roman":"Umar ibn al-Khattab (RA)","ur":"عمر بن خطاب رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Sa'd ibn Abi Waqqas (RA)","roman":"Sa'd ibn Abi Waqqas (RA)","ur":"سعد بن ابی وقاص رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Umar (RA) was called Al-Faruq, the one who distinguishes truth from falsehood.","roman":"Hazrat Umar (RA) ko Farooq kaha gaya, yaani haq aur batil mein farq karne wala.","ur":"حضرت عمر رضی اللہ عنہ کو فاروق کہا گیا، یعنی حق اور باطل میں فرق کرنے والا۔"}$q$::jsonb,$q$Established title$q$,$q$seerah$q$),
($q$s32$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which companion was given the title \"Sword of Allah\"?","roman":"Kis sahabi ko \"Saifullah\" (Allah ki talwar) ka laqab mila?","ur":"کس صحابی کو \"سیف اللہ\" کا لقب ملا؟"}$q$::jsonb,$q$[{"en":"Khalid ibn al-Walid (RA)","roman":"Khalid ibn al-Walid (RA)","ur":"خالد بن ولید رضی اللہ عنہ"},{"en":"Hamzah (RA)","roman":"Hamzah (RA)","ur":"حمزہ رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Zubair (RA)","roman":"Zubair (RA)","ur":"زبیر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"At the Battle of Mu'tah the Prophet ﷺ called Khalid (RA) \"a sword from the swords of Allah\".","roman":"Jung-e-Mutah ke mauqe par Nabi ﷺ ne Hazrat Khalid (RA) ko \"Allah ki talwaron mein se ek talwar\" kaha.","ur":"جنگِ موتہ کے موقع پر نبی ﷺ نے حضرت خالد رضی اللہ عنہ کو \"اللہ کی تلواروں میں سے ایک تلوار\" کہا۔"}$q$::jsonb,$q$Sahih al-Bukhari 4262$q$,$q$seerah$q$),
($q$s33$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Which uncle of the Prophet ﷺ was called the \"Lion of Allah\" and was martyred at Uhud?","roman":"Nabi ﷺ ke kis chacha ko \"Asadullah\" kaha gaya aur woh Uhud mein shaheed hue?","ur":"نبی ﷺ کے کس چچا کو \"اسد اللہ\" کہا گیا اور وہ احد میں شہید ہوئے؟"}$q$::jsonb,$q$[{"en":"Hamzah ibn Abdul-Muttalib (RA)","roman":"Hamzah ibn Abdul-Muttalib (RA)","ur":"حمزہ بن عبدالمطلب رضی اللہ عنہ"},{"en":"Abbas (RA)","roman":"Abbas (RA)","ur":"عباس رضی اللہ عنہ"},{"en":"Abu Talib","roman":"Abu Talib","ur":"ابو طالب"},{"en":"Abu Lahab","roman":"Abu Lahab","ur":"ابو لہب"}]$q$::jsonb,0,$q${"en":"Hamzah (RA) was martyred at the Battle of Uhud in 3 AH.","roman":"Hazrat Hamzah (RA) 3 Hijri mein Jung-e-Uhud mein shaheed hue.","ur":"حضرت حمزہ رضی اللہ عنہ 3 ہجری میں جنگِ احد میں شہید ہوئے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$s34$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Which uncle of the Prophet ﷺ is condemned by name in the Quran?","roman":"Nabi ﷺ ke kis chacha ka naam le kar Quran mein mazammat ki gayi?","ur":"نبی ﷺ کے کس چچا کا نام لے کر قرآن میں مذمت کی گئی؟"}$q$::jsonb,$q$[{"en":"Abu Lahab","roman":"Abu Lahab","ur":"ابو لہب"},{"en":"Abu Talib","roman":"Abu Talib","ur":"ابو طالب"},{"en":"Abbas","roman":"Abbas","ur":"عباس"},{"en":"Abu Jahl","roman":"Abu Jahl","ur":"ابو جہل"}]$q$::jsonb,0,$q${"en":"Surah Al-Masad (111) names Abu Lahab for his hostility to the message.","roman":"Surah Al-Masad (111) mein Abu Lahab ka naam us ki dushmani ki wajah se aaya.","ur":"سورۃ المسد (111) میں ابو لہب کا نام اس کی دشمنی کی وجہ سے آیا۔"}$q$::jsonb,$q$Quran 111$q$,$q$quran$q$),
($q$s35$q$,$q$history$q$,$q$published$q$,$q${"en":"During whose caliphate was the Hijri calendar established?","roman":"Hijri calendar kis khalifa ke daur mein shuru hua?","ur":"ہجری کیلنڈر کس خلیفہ کے دور میں شروع ہوا؟"}$q$::jsonb,$q$[{"en":"Umar ibn al-Khattab (RA)","roman":"Umar ibn al-Khattab (RA)","ur":"عمر بن خطاب رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Umar (RA) adopted the Hijrah as year one of the Islamic calendar.","roman":"Hazrat Umar (RA) ne Hijrat ke saal ko Islami calendar ka pehla saal muqarrar kiya.","ur":"حضرت عمر رضی اللہ عنہ نے ہجرت کے سال کو اسلامی کیلنڈر کا پہلا سال مقرر کیا۔"}$q$::jsonb,$q$Tarikh al-Tabari$q$,$q$seerah$q$),
($q$a01$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet built the Ark?","roman":"Kashti kis nabi ne banai?","ur":"کشتی کس نبی نے بنائی؟"}$q$::jsonb,$q$[{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Yunus (AS)","roman":"Yunus (AS)","ur":"یونس علیہ السلام"}]$q$::jsonb,0,$q${"en":"Allah commanded Nuh (AS) to build the Ark before the flood (11:37).","roman":"Allah ne Hazrat Nuh (AS) ko toofan se pehle kashti banane ka hukm diya (11:37).","ur":"اللہ نے حضرت نوح علیہ السلام کو طوفان سے پہلے کشتی بنانے کا حکم دیا (11:37)۔"}$q$::jsonb,$q$Quran 11:37–44$q$,$q$quran$q$),
($q$a02$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was swallowed by a large fish?","roman":"Kis nabi ko bari machhli ne nigal liya?","ur":"کس نبی کو بڑی مچھلی نے نگل لیا؟"}$q$::jsonb,$q$[{"en":"Yunus (AS)","roman":"Yunus (AS)","ur":"یونس علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Ayyub (AS)","roman":"Ayyub (AS)","ur":"ایوب علیہ السلام"},{"en":"Ilyas (AS)","roman":"Ilyas (AS)","ur":"الیاس علیہ السلام"}]$q$::jsonb,0,$q${"en":"Yunus (AS) was swallowed by the fish and glorified Allah inside it (37:142–144, 21:87).","roman":"Hazrat Yunus (AS) ko machhli ne nigla aur unhon ne us ke andar Allah ki tasbeeh ki (37:142–144, 21:87).","ur":"حضرت یونس علیہ السلام کو مچھلی نے نگلا اور انہوں نے اس کے اندر اللہ کی تسبیح کی (37:142–144، 21:87)۔"}$q$::jsonb,$q$Quran 37:139–144$q$,$q$quran$q$),
($q$a03$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"For which prophet did Allah make the fire cool and safe?","roman":"Allah ne kis nabi ke liye aag ko thanda aur salamati wala bana diya?","ur":"اللہ نے کس نبی کے لیے آگ کو ٹھنڈا اور سلامتی والا بنا دیا؟"}$q$::jsonb,$q$[{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Lut (AS)","roman":"Lut (AS)","ur":"لوط علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"O fire, be coolness and safety upon Ibrahim\" (21:69).","roman":"\"Aye aag, Ibrahim par thandi aur salamati wali ho ja\" (21:69).","ur":"\"اے آگ، ابراہیم پر ٹھنڈی اور سلامتی والی ہو جا\" (21:69)۔"}$q$::jsonb,$q$Quran 21:68–69$q$,$q$quran$q$),
($q$a04$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was given the Zabur?","roman":"Zaboor kis nabi ko di gayi?","ur":"زبور کس نبی کو دی گئی؟"}$q$::jsonb,$q$[{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And to Dawud We gave the Zabur\" (4:163).","roman":"\"Aur Dawood ko hum ne Zaboor di\" (4:163).","ur":"\"اور داؤد کو ہم نے زبور دی\" (4:163)۔"}$q$::jsonb,$q$Quran 4:163$q$,$q$quran$q$),
($q$a05$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Allah spoke directly to which prophet?","roman":"Allah ne kis nabi se baraah-e-raast kalaam kiya?","ur":"اللہ نے کس نبی سے براہِ راست کلام کیا؟"}$q$::jsonb,$q$[{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Harun (AS)","roman":"Harun (AS)","ur":"ہارون علیہ السلام"},{"en":"Yusuf (AS)","roman":"Yusuf (AS)","ur":"یوسف علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And Allah spoke to Musa with direct speech\" (4:164). He is called Kalimullah.","roman":"\"Aur Allah ne Musa se kalaam kiya\" (4:164). Unhein Kaleemullah kaha jata hai.","ur":"\"اور اللہ نے موسیٰ سے کلام کیا\" (4:164)۔ انہیں کلیم اللہ کہا جاتا ہے۔"}$q$::jsonb,$q$Quran 4:164$q$,$q$quran$q$),
($q$a06$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was given the Injil?","roman":"Injeel kis nabi ko di gayi?","ur":"انجیل کس نبی کو دی گئی؟"}$q$::jsonb,$q$[{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Yahya (AS)","roman":"Yahya (AS)","ur":"یحییٰ علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And We gave him the Injil\" refers to Isa ibn Maryam (5:46).","roman":"\"Aur hum ne usay Injeel di\" Isa ibn Maryam ke baare mein hai (5:46).","ur":"\"اور ہم نے اسے انجیل دی\" عیسیٰ ابن مریم کے بارے میں ہے (5:46)۔"}$q$::jsonb,$q$Quran 5:46$q$,$q$quran$q$),
($q$a07$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophets raised the foundations of the Ka'bah?","roman":"Kaaba ki buniyadein kin anbiya ne uthayin?","ur":"کعبہ کی بنیادیں کن انبیاء نے اٹھائیں؟"}$q$::jsonb,$q$[{"en":"Ibrahim and Isma'il (AS)","roman":"Ibrahim and Isma'il (AS)","ur":"ابراہیم اور اسماعیل علیہما السلام"},{"en":"Musa and Harun (AS)","roman":"Musa and Harun (AS)","ur":"موسیٰ اور ہارون علیہما السلام"},{"en":"Dawud and Sulaiman (AS)","roman":"Dawud and Sulaiman (AS)","ur":"داؤد اور سلیمان علیہما السلام"},{"en":"Zakariya and Yahya (AS)","roman":"Zakariya and Yahya (AS)","ur":"زکریا اور یحییٰ علیہما السلام"}]$q$::jsonb,0,$q${"en":"\"And when Ibrahim was raising the foundations of the House, and Isma'il…\" (2:127).","roman":"\"Aur jab Ibrahim aur Ismail Ghar ki buniyadein utha rahe the…\" (2:127).","ur":"\"اور جب ابراہیم اور اسماعیل گھر کی بنیادیں اٹھا رہے تھے…\" (2:127)۔"}$q$::jsonb,$q$Quran 2:127$q$,$q$quran$q$),
($q$a08$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Whose story does the Quran call \"the best of stories\"?","roman":"Quran ne kis ke qisse ko \"ahsan-ul-qasas\" kaha?","ur":"قرآن نے کس کے قصے کو \"احسن القصص\" کہا؟"}$q$::jsonb,$q$[{"en":"Yusuf (AS)","roman":"Yusuf (AS)","ur":"یوسف علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"}]$q$::jsonb,0,$q${"en":"Surah Yusuf opens by calling it the best of stories (12:3).","roman":"Surah Yusuf ke aaghaz mein isay behtareen qissa kaha gaya (12:3).","ur":"سورۃ یوسف کے آغاز میں اسے بہترین قصہ کہا گیا (12:3)۔"}$q$::jsonb,$q$Quran 12:3$q$,$q$quran$q$),
($q$a09$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"For which prophet did Allah make the wind subservient?","roman":"Allah ne kis nabi ke liye hawa ko taabe kar diya?","ur":"اللہ نے کس نبی کے لیے ہوا کو تابع کر دیا؟"}$q$::jsonb,$q$[{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"},{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Hud (AS)","roman":"Hud (AS)","ur":"ہود علیہ السلام"},{"en":"Salih (AS)","roman":"Salih (AS)","ur":"صالح علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And to Sulaiman the wind…\" (34:12, 21:81).","roman":"\"Aur Sulaiman ke liye hawa…\" (34:12, 21:81).","ur":"\"اور سلیمان کے لیے ہوا…\" (34:12، 21:81)۔"}$q$::jsonb,$q$Quran 34:12; 21:81$q$,$q$quran$q$),
($q$a10$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"The she-camel was a sign given to which prophet's people?","roman":"Oontni kis nabi ki qaum ke liye nishani thi?","ur":"اونٹنی کس نبی کی قوم کے لیے نشانی تھی؟"}$q$::jsonb,$q$[{"en":"Salih (AS), to Thamud","roman":"Salih (AS), to Thamud","ur":"صالح علیہ السلام، قومِ ثمود"},{"en":"Hud (AS), to Aad","roman":"Hud (AS), to Aad","ur":"ہود علیہ السلام، قومِ عاد"},{"en":"Shu'aib (AS), to Madyan","roman":"Shu'aib (AS), to Madyan","ur":"شعیب علیہ السلام، مدین"},{"en":"Lut (AS)","roman":"Lut (AS)","ur":"لوط علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"This is the she-camel of Allah, a sign for you\" — Salih (AS) to Thamud (7:73).","roman":"\"Yeh Allah ki oontni hai, tumhare liye nishani\" — Hazrat Saleh (AS) ne Samood se kaha (7:73).","ur":"\"یہ اللہ کی اونٹنی ہے، تمہارے لیے نشانی\" — حضرت صالح علیہ السلام نے ثمود سے کہا (7:73)۔"}$q$::jsonb,$q$Quran 7:73$q$,$q$quran$q$),
($q$a11$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was sent to the people of Aad?","roman":"Qaum-e-Aad ki taraf kaunse nabi bheje gaye?","ur":"قومِ عاد کی طرف کون سے نبی بھیجے گئے؟"}$q$::jsonb,$q$[{"en":"Hud (AS)","roman":"Hud (AS)","ur":"ہود علیہ السلام"},{"en":"Salih (AS)","roman":"Salih (AS)","ur":"صالح علیہ السلام"},{"en":"Shu'aib (AS)","roman":"Shu'aib (AS)","ur":"شعیب علیہ السلام"},{"en":"Idris (AS)","roman":"Idris (AS)","ur":"ادریس علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And to Aad [We sent] their brother Hud\" (7:65).","roman":"\"Aur Aad ki taraf un ke bhai Hood ko\" (7:65).","ur":"\"اور عاد کی طرف ان کے بھائی ہود کو\" (7:65)۔"}$q$::jsonb,$q$Quran 7:65$q$,$q$quran$q$),
($q$a12$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was sent to the people of Madyan?","roman":"Madyan walon ki taraf kaunse nabi bheje gaye?","ur":"مدین والوں کی طرف کون سے نبی بھیجے گئے؟"}$q$::jsonb,$q$[{"en":"Shu'aib (AS)","roman":"Shu'aib (AS)","ur":"شعیب علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Hud (AS)","roman":"Hud (AS)","ur":"ہود علیہ السلام"},{"en":"Yunus (AS)","roman":"Yunus (AS)","ur":"یونس علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And to Madyan [We sent] their brother Shu'aib\" (7:85).","roman":"\"Aur Madyan ki taraf un ke bhai Shuaib ko\" (7:85).","ur":"\"اور مدین کی طرف ان کے بھائی شعیب کو\" (7:85)۔"}$q$::jsonb,$q$Quran 7:85$q$,$q$quran$q$),
($q$a13$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet was given a name that no one had before him?","roman":"Kis nabi ko aisa naam diya gaya jo pehle kisi ka nahi tha?","ur":"کس نبی کو ایسا نام دیا گیا جو پہلے کسی کا نہیں تھا؟"}$q$::jsonb,$q$[{"en":"Yahya (AS)","roman":"Yahya (AS)","ur":"یحییٰ علیہ السلام"},{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Ishaq (AS)","roman":"Ishaq (AS)","ur":"اسحاق علیہ السلام"},{"en":"Ya'qub (AS)","roman":"Ya'qub (AS)","ur":"یعقوب علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"Indeed We give you good news of a boy whose name will be Yahya; We have not assigned this name to anyone before\" (19:7).","roman":"\"Hum tumhein ek larke ki khushkhabri dete hain jis ka naam Yahya hoga, is naam ka pehle koi nahi banaya\" (19:7).","ur":"\"ہم تمہیں ایک لڑکے کی خوشخبری دیتے ہیں جس کا نام یحییٰ ہوگا، اس نام کا پہلے کوئی نہیں بنایا\" (19:7)۔"}$q$::jsonb,$q$Quran 19:7$q$,$q$quran$q$),
($q$a14$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet is known for patience through long illness?","roman":"Kaunse nabi lambi beemari mein sabr ke liye mashhoor hain?","ur":"کون سے نبی لمبی بیماری میں صبر کے لیے مشہور ہیں؟"}$q$::jsonb,$q$[{"en":"Ayyub (AS)","roman":"Ayyub (AS)","ur":"ایوب علیہ السلام"},{"en":"Yaqub (AS)","roman":"Yaqub (AS)","ur":"یعقوب علیہ السلام"},{"en":"Yunus (AS)","roman":"Yunus (AS)","ur":"یونس علیہ السلام"},{"en":"Zakariya (AS)","roman":"Zakariya (AS)","ur":"زکریا علیہ السلام"}]$q$::jsonb,0,$q${"en":"Ayyub (AS) called upon his Lord in his hardship and Allah relieved him (21:83–84, 38:44).","roman":"Hazrat Ayyub (AS) ne museebat mein Rab ko pukara aur Allah ne takleef door ki (21:83–84, 38:44).","ur":"حضرت ایوب علیہ السلام نے مصیبت میں رب کو پکارا اور اللہ نے تکلیف دور کی (21:83–84، 38:44)۔"}$q$::jsonb,$q$Quran 21:83–84$q$,$q$quran$q$),
($q$a15$q$,$q$ambiya$q$,$q$published$q$,$q${"en":"Which prophet gave good news of a messenger named Ahmad?","roman":"Kis nabi ne Ahmad naam ke rasool ki khushkhabri di?","ur":"کس نبی نے احمد نام کے رسول کی خوشخبری دی؟"}$q$::jsonb,$q$[{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Yahya (AS)","roman":"Yahya (AS)","ur":"یحییٰ علیہ السلام"}]$q$::jsonb,0,$q${"en":"Isa (AS) said: \"…bringing good news of a messenger after me whose name is Ahmad\" (61:6).","roman":"Hazrat Isa (AS) ne kaha: \"…mere baad aane wale rasool ki khushkhabri jinka naam Ahmad hai\" (61:6).","ur":"حضرت عیسیٰ علیہ السلام نے کہا: \"…میرے بعد آنے والے رسول کی خوشخبری جن کا نام احمد ہے\" (61:6)۔"}$q$::jsonb,$q$Quran 61:6$q$,$q$quran$q$),
($q$q01$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which ayah calls the Prophet ﷺ the \"Seal of the Prophets\"?","roman":"Kaunsi ayat Nabi ﷺ ko \"Khatam-un-Nabiyyin\" kehti hai?","ur":"کون سی آیت نبی ﷺ کو \"خاتم النبیین\" کہتی ہے؟"}$q$::jsonb,$q$[{"en":"Al-Ahzab 33:40","roman":"Al-Ahzab 33:40","ur":"الاحزاب 33:40"},{"en":"Al-Baqarah 2:255","roman":"Al-Baqarah 2:255","ur":"البقرہ 2:255"},{"en":"Al-Fath 48:29","roman":"Al-Fath 48:29","ur":"الفتح 48:29"},{"en":"Al-Anbiya 21:107","roman":"Al-Anbiya 21:107","ur":"الانبیاء 21:107"}]$q$::jsonb,0,$q${"en":"\"Muhammad is not the father of any of your men, but he is the Messenger of Allah and the Seal of the Prophets\" (33:40).","roman":"\"Muhammad tumhare mardon mein se kisi ke baap nahi, balke Allah ke Rasool aur Khatam-un-Nabiyyin hain\" (33:40).","ur":"\"محمد تمہارے مردوں میں سے کسی کے باپ نہیں، بلکہ اللہ کے رسول اور خاتم النبیین ہیں\" (33:40)۔"}$q$::jsonb,$q$Quran 33:40$q$,$q$quran$q$),
($q$q02$q$,$q$quranic$q$,$q$published$q$,$q${"en":"In which night was the Quran sent down, according to Surah Al-Qadr?","roman":"Surah Al-Qadr ke mutabiq Quran kis raat nazil hua?","ur":"سورۃ القدر کے مطابق قرآن کس رات نازل ہوا؟"}$q$::jsonb,$q$[{"en":"Laylat al-Qadr","roman":"Laylat al-Qadr","ur":"لیلۃ القدر"},{"en":"The night of Isra","roman":"The night of Isra","ur":"شبِ اسراء"},{"en":"The 15th of Sha'ban","roman":"The 15th of Sha'ban","ur":"پندرہ شعبان"},{"en":"The night of Eid","roman":"The night of Eid","ur":"عید کی رات"}]$q$::jsonb,0,$q${"en":"\"Indeed, We sent it down during the Night of Decree\" (97:1), which is in Ramadan (2:185).","roman":"\"Beshak hum ne isay Shab-e-Qadr mein nazil kiya\" (97:1), jo Ramadan mein hai (2:185).","ur":"\"بے شک ہم نے اسے شبِ قدر میں نازل کیا\" (97:1)، جو رمضان میں ہے (2:185)۔"}$q$::jsonb,$q$Quran 97:1$q$,$q$quran$q$),
($q$q03$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which surah contains the command to fast in Ramadan?","roman":"Ramadan ke roze ka hukm kis surah mein hai?","ur":"رمضان کے روزے کا حکم کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Baqarah","roman":"Al-Baqarah","ur":"البقرہ"},{"en":"Al-Imran","roman":"Al-Imran","ur":"آل عمران"},{"en":"An-Nisa","roman":"An-Nisa","ur":"النساء"},{"en":"Al-Ma'idah","roman":"Al-Ma'idah","ur":"المائدہ"}]$q$::jsonb,0,$q${"en":"\"O you who believe, fasting is prescribed for you…\" (2:183–185).","roman":"\"Aye iman walo, tum par roze farz kiye gaye…\" (2:183–185).","ur":"\"اے ایمان والو، تم پر روزے فرض کیے گئے…\" (2:183–185)۔"}$q$::jsonb,$q$Quran 2:183$q$,$q$quran$q$),
($q$q04$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which surah does not begin with Bismillah?","roman":"Kaunsi surah Bismillah se shuru nahi hoti?","ur":"کون سی سورت بسم اللہ سے شروع نہیں ہوتی؟"}$q$::jsonb,$q$[{"en":"At-Tawbah","roman":"At-Tawbah","ur":"التوبہ"},{"en":"Al-Anfal","roman":"Al-Anfal","ur":"الانفال"},{"en":"Al-Fatihah","roman":"Al-Fatihah","ur":"الفاتحہ"},{"en":"An-Naml","roman":"An-Naml","ur":"النمل"}]$q$::jsonb,0,$q${"en":"Surah At-Tawbah (9) is the only surah that does not open with Bismillah.","roman":"Surah At-Taubah (9) wahid surah hai jo Bismillah se shuru nahi hoti.","ur":"سورۃ التوبہ (9) واحد سورت ہے جو بسم اللہ سے شروع نہیں ہوتی۔"}$q$::jsonb,$q$Quran 9:1$q$,$q$quran$q$),
($q$q05$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which surah contains Bismillah twice?","roman":"Kis surah mein Bismillah do dafa hai?","ur":"کس سورت میں بسم اللہ دو بار ہے؟"}$q$::jsonb,$q$[{"en":"An-Naml","roman":"An-Naml","ur":"النمل"},{"en":"At-Tawbah","roman":"At-Tawbah","ur":"التوبہ"},{"en":"Al-Fatihah","roman":"Al-Fatihah","ur":"الفاتحہ"},{"en":"Al-Kahf","roman":"Al-Kahf","ur":"الکہف"}]$q$::jsonb,0,$q${"en":"Besides its opening, Surah An-Naml has Bismillah in Sulaiman's (AS) letter (27:30).","roman":"Shuru ke ilawa Surah An-Naml mein Hazrat Sulaiman (AS) ke khat mein Bismillah hai (27:30).","ur":"شروع کے علاوہ سورۃ النمل میں حضرت سلیمان علیہ السلام کے خط میں بسم اللہ ہے (27:30)۔"}$q$::jsonb,$q$Quran 27:30$q$,$q$quran$q$),
($q$q06$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which is the longest ayah in the Quran?","roman":"Quran ki sab se lambi ayat kaunsi hai?","ur":"قرآن کی سب سے لمبی آیت کون سی ہے؟"}$q$::jsonb,$q$[{"en":"Al-Baqarah 2:282 (the ayah of debt)","roman":"Al-Baqarah 2:282 (the ayah of debt)","ur":"البقرہ 2:282 (آیتِ دین)"},{"en":"Ayat al-Kursi 2:255","roman":"Ayat al-Kursi 2:255","ur":"آیت الکرسی 2:255"},{"en":"An-Nur 24:35","roman":"An-Nur 24:35","ur":"النور 24:35"},{"en":"Al-Baqarah 2:286","roman":"Al-Baqarah 2:286","ur":"البقرہ 2:286"}]$q$::jsonb,0,$q${"en":"2:282, about recording debts, is the longest ayah of the Quran.","roman":"2:282, qarz likhne ke baare mein, Quran ki sab se lambi ayat hai.","ur":"2:282، قرض لکھنے کے بارے میں، قرآن کی سب سے لمبی آیت ہے۔"}$q$::jsonb,$q$Quran 2:282$q$,$q$quran$q$),
($q$r01$q$,$q$research$q$,$q$published$q$,$q${"en":"Who is remembered as the \"Lady of Uhud\", the woman who fought to shield the Prophet ﷺ in that battle?","roman":"\"Khatoon-e-Uhud\" kaun thin, jinhon ne Uhud mein Nabi ﷺ ki hifazat ke liye jung ki?","ur":"\"خاتونِ احد\" کون تھیں، جنہوں نے احد میں نبی ﷺ کی حفاظت کے لیے جنگ کی؟"}$q$::jsonb,$q$[{"en":"Nusaybah bint Ka'b (Umm Ammarah) (RA)","roman":"Nusaybah bint Ka'b (Umm Ammarah) (RA)","ur":"نسیبہ بنت کعب (ام عمارہ) رضی اللہ عنہا"},{"en":"Khawlah bint al-Azwar","roman":"Khawlah bint al-Azwar","ur":"خولہ بنت الازور"},{"en":"Asma bint Abi Bakr (RA)","roman":"Asma bint Abi Bakr (RA)","ur":"اسماء بنت ابی بکر رضی اللہ عنہا"},{"en":"Safiyyah bint Abdul-Muttalib (RA)","roman":"Safiyyah bint Abdul-Muttalib (RA)","ur":"صفیہ بنت عبدالمطلب رضی اللہ عنہا"}]$q$::jsonb,0,$q${"en":"Nusaybah bint Ka'b (RA) came to Uhud to give water to the wounded; when the line broke she fought beside the Prophet ﷺ and was wounded many times.","roman":"Hazrat Nusaybah bint Ka'b (RA) Uhud mein zakhmiyon ko pani pilane aayi thin; jab saf toot gayi to Nabi ﷺ ke paas lareen aur kai zakhm khaye.","ur":"حضرت نسیبہ بنت کعب رضی اللہ عنہا احد میں زخمیوں کو پانی پلانے آئی تھیں؛ جب صف ٹوٹ گئی تو نبی ﷺ کے پاس لڑیں اور کئی زخم کھائے۔"}$q$::jsonb,$q$Ibn Hisham, As-Sirah an-Nabawiyyah (Uhud); Ibn Sa'd, At-Tabaqat al-Kubra$q$,$q$seerah$q$),
($q$r02$q$,$q$research$q$,$q$published$q$,$q${"en":"Which woman earned the title \"She of the Two Belts\" (Dhat an-Nitaqayn) during the Hijrah?","roman":"Hijrat ke dauran kis khatoon ko \"Zaat-un-Nitaqain\" (do kamarbandon wali) ka laqab mila?","ur":"ہجرت کے دوران کس خاتون کو \"ذات النطاقین\" کا لقب ملا؟"}$q$::jsonb,$q$[{"en":"Asma bint Abi Bakr (RA)","roman":"Asma bint Abi Bakr (RA)","ur":"اسماء بنت ابی بکر رضی اللہ عنہا"},{"en":"Aishah (RA)","roman":"Aishah (RA)","ur":"عائشہ رضی اللہ عنہا"},{"en":"Fatimah (RA)","roman":"Fatimah (RA)","ur":"فاطمہ رضی اللہ عنہا"},{"en":"Umm Salamah (RA)","roman":"Umm Salamah (RA)","ur":"ام سلمہ رضی اللہ عنہا"}]$q$::jsonb,0,$q${"en":"She tore her waist belt in two to tie up the food for the Prophet ﷺ and Abu Bakr (RA) as they left for the cave.","roman":"Unhon ne apna kamarband do hisson mein phaar kar Nabi ﷺ aur Hazrat Abu Bakr (RA) ka khana baandha jab woh ghaar ki taraf nikle.","ur":"انہوں نے اپنا کمربند دو حصوں میں پھاڑ کر نبی ﷺ اور حضرت ابو بکر رضی اللہ عنہ کا کھانا باندھا جب وہ غار کی طرف نکلے۔"}$q$::jsonb,$q$Sahih al-Bukhari 2979$q$,$q$seerah$q$),
($q$r03$q$,$q$research$q$,$q$published$q$,$q${"en":"Which companion did the Prophet ﷺ call \"the trustworthy one of this ummah\" (Amin al-Ummah)?","roman":"Nabi ﷺ ne kis sahabi ko \"is ummat ka ameen\" kaha?","ur":"نبی ﷺ نے کس صحابی کو \"اس امت کا امین\" کہا؟"}$q$::jsonb,$q$[{"en":"Abu Ubaydah ibn al-Jarrah (RA)","roman":"Abu Ubaydah ibn al-Jarrah (RA)","ur":"ابو عبیدہ بن الجراح رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Abdur-Rahman ibn Awf (RA)","roman":"Abdur-Rahman ibn Awf (RA)","ur":"عبدالرحمٰن بن عوف رضی اللہ عنہ"},{"en":"Sa'd ibn Abi Waqqas (RA)","roman":"Sa'd ibn Abi Waqqas (RA)","ur":"سعد بن ابی وقاص رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"\"Every nation has a trustworthy one, and the trustworthy one of this ummah is Abu Ubaydah ibn al-Jarrah.\"","roman":"\"Har ummat ka ek ameen hota hai, aur is ummat ke ameen Abu Ubaidah bin Jarrah hain.\"","ur":"\"ہر امت کا ایک امین ہوتا ہے، اور اس امت کے امین ابو عبیدہ بن الجراح ہیں۔\""}$q$::jsonb,$q$Sahih al-Bukhari 3744$q$,$q$seerah$q$),
($q$r04$q$,$q$research$q$,$q$published$q$,$q${"en":"At whose death did the Throne of the Most Merciful shake, as the Prophet ﷺ said?","roman":"Nabi ﷺ ke farmaan ke mutabiq kis ki wafat par Arsh-e-Rahman hil gaya?","ur":"نبی ﷺ کے فرمان کے مطابق کس کی وفات پر عرشِ رحمٰن ہل گیا؟"}$q$::jsonb,$q$[{"en":"Sa'd ibn Mu'adh (RA)","roman":"Sa'd ibn Mu'adh (RA)","ur":"سعد بن معاذ رضی اللہ عنہ"},{"en":"Hamzah (RA)","roman":"Hamzah (RA)","ur":"حمزہ رضی اللہ عنہ"},{"en":"Mus'ab ibn Umair (RA)","roman":"Mus'ab ibn Umair (RA)","ur":"مصعب بن عمیر رضی اللہ عنہ"},{"en":"Ja'far ibn Abi Talib (RA)","roman":"Ja'far ibn Abi Talib (RA)","ur":"جعفر بن ابی طالب رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Sa'd ibn Mu'adh (RA), chief of the Aws, died of a wound from the Battle of the Trench.","roman":"Aus ke sardar Hazrat Saad bin Muaz (RA) Jung-e-Khandaq ke zakhm se shaheed hue.","ur":"اوس کے سردار حضرت سعد بن معاذ رضی اللہ عنہ جنگِ خندق کے زخم سے شہید ہوئے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3803$q$,$q$seerah$q$),
($q$r05$q$,$q$research$q$,$q$published$q$,$q${"en":"Which martyr of Uhud was called \"the one washed by the angels\" (Ghasil al-Mala'ikah)?","roman":"Uhud ke kis shaheed ko \"Ghaseel-ul-Malaika\" (farishton ka ghusl diya hua) kaha gaya?","ur":"احد کے کس شہید کو \"غسیل الملائکہ\" کہا گیا؟"}$q$::jsonb,$q$[{"en":"Hanzalah ibn Abi Amir (RA)","roman":"Hanzalah ibn Abi Amir (RA)","ur":"حنظلہ بن ابی عامر رضی اللہ عنہ"},{"en":"Hamzah (RA)","roman":"Hamzah (RA)","ur":"حمزہ رضی اللہ عنہ"},{"en":"Anas ibn an-Nadr (RA)","roman":"Anas ibn an-Nadr (RA)","ur":"انس بن نضر رضی اللہ عنہ"},{"en":"Abdullah ibn Jahsh (RA)","roman":"Abdullah ibn Jahsh (RA)","ur":"عبداللہ بن جحش رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Hanzalah (RA) rushed to Uhud on the morning after his wedding; the Prophet ﷺ said the angels were washing him.","roman":"Hazrat Hanzalah (RA) shadi ki agli subah Uhud ki taraf daure; Nabi ﷺ ne farmaya ke farishte unhein ghusl de rahe hain.","ur":"حضرت حنظلہ رضی اللہ عنہ شادی کی اگلی صبح احد کی طرف دوڑے؛ نبی ﷺ نے فرمایا کہ فرشتے انہیں غسل دے رہے ہیں۔"}$q$::jsonb,$q$Ibn Hisham (Uhud)$q$,$q$seerah$q$),
($q$r06$q$,$q$research$q$,$q$published$q$,$q${"en":"\"Every prophet has a disciple (hawari), and my disciple is…\" — whom did the Prophet ﷺ name?","roman":"\"Har nabi ka ek hawari hota hai, aur mera hawari…\" Nabi ﷺ ne kis ka naam liya?","ur":"\"ہر نبی کا ایک حواری ہوتا ہے، اور میرا حواری…\" نبی ﷺ نے کس کا نام لیا؟"}$q$::jsonb,$q$[{"en":"Zubair ibn al-Awwam (RA)","roman":"Zubair ibn al-Awwam (RA)","ur":"زبیر بن العوام رضی اللہ عنہ"},{"en":"Talhah (RA)","roman":"Talhah (RA)","ur":"طلحہ رضی اللہ عنہ"},{"en":"Ali (RA)","roman":"Ali (RA)","ur":"علی رضی اللہ عنہ"},{"en":"Bilal (RA)","roman":"Bilal (RA)","ur":"بلال رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"The Prophet ﷺ said this about Zubair (RA) when he volunteered to bring news of the enemy at the Trench.","roman":"Nabi ﷺ ne yeh Hazrat Zubair (RA) ke baare mein farmaya jab woh Khandaq mein dushman ki khabar laane ke liye aage bare.","ur":"نبی ﷺ نے یہ حضرت زبیر رضی اللہ عنہ کے بارے میں فرمایا جب وہ خندق میں دشمن کی خبر لانے کے لیے آگے بڑھے۔"}$q$::jsonb,$q$Sahih al-Bukhari 2846$q$,$q$seerah$q$),
($q$r07$q$,$q$research$q$,$q$published$q$,$q${"en":"Which young scribe of revelation was given the task of gathering the Quran into one copy under Abu Bakr (RA)?","roman":"Wahi ke kis jawan katib ko Hazrat Abu Bakr (RA) ke daur mein Quran ek jagah jama karne ka kaam diya gaya?","ur":"وحی کے کس نوجوان کاتب کو حضرت ابو بکر رضی اللہ عنہ کے دور میں قرآن ایک جگہ جمع کرنے کا کام دیا گیا؟"}$q$::jsonb,$q$[{"en":"Zaid ibn Thabit (RA)","roman":"Zaid ibn Thabit (RA)","ur":"زید بن ثابت رضی اللہ عنہ"},{"en":"Ubayy ibn Ka'b (RA)","roman":"Ubayy ibn Ka'b (RA)","ur":"ابی بن کعب رضی اللہ عنہ"},{"en":"Abdullah ibn Mas'ud (RA)","roman":"Abdullah ibn Mas'ud (RA)","ur":"عبداللہ بن مسعود رضی اللہ عنہ"},{"en":"Mu'adh ibn Jabal (RA)","roman":"Mu'adh ibn Jabal (RA)","ur":"معاذ بن جبل رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"After many reciters were martyred at Yamamah, Abu Bakr (RA), on Umar's (RA) advice, asked Zaid ibn Thabit (RA) to collect the Quran.","roman":"Yamamah mein bohat se qari shaheed hue to Hazrat Umar (RA) ke mashware par Hazrat Abu Bakr (RA) ne Hazrat Zaid bin Sabit (RA) ko Quran jama karne ko kaha.","ur":"یمامہ میں بہت سے قاری شہید ہوئے تو حضرت عمر رضی اللہ عنہ کے مشورے پر حضرت ابو بکر رضی اللہ عنہ نے حضرت زید بن ثابت رضی اللہ عنہ کو قرآن جمع کرنے کو کہا۔"}$q$::jsonb,$q$Sahih al-Bukhari 4986$q$,$q$seerah$q$),
($q$r08$q$,$q$research$q$,$q$published$q$,$q${"en":"\"The first of you to join me will be the one with the longest hand.\" Which Mother of the Believers was it, \"long-handed\" in charity?","roman":"\"Tum mein se sab se pehle mujh se woh milegi jis ka haath sab se lamba hai.\" Kaunsi Umm-ul-Momineen thin, sadqe mein \"lambe haath\" wali?","ur":"\"تم میں سے سب سے پہلے مجھ سے وہ ملے گی جس کا ہاتھ سب سے لمبا ہے۔\" کون سی ام المؤمنین تھیں، صدقے میں \"لمبے ہاتھ\" والی؟"}$q$::jsonb,$q$[{"en":"Zaynab bint Jahsh (RA)","roman":"Zaynab bint Jahsh (RA)","ur":"زینب بنت جحش رضی اللہ عنہا"},{"en":"Sawdah (RA)","roman":"Sawdah (RA)","ur":"سودہ رضی اللہ عنہا"},{"en":"Aishah (RA)","roman":"Aishah (RA)","ur":"عائشہ رضی اللہ عنہا"},{"en":"Hafsah (RA)","roman":"Hafsah (RA)","ur":"حفصہ رضی اللہ عنہا"}]$q$::jsonb,0,$q${"en":"Zaynab bint Jahsh (RA) was the first of the Prophet's ﷺ wives to pass away after him; she worked with her hands and gave in charity.","roman":"Hazrat Zainab bint Jahsh (RA) Nabi ﷺ ke baad sab se pehle wafat paane wali zauja thin; woh haath se kaam karti aur sadqa deti thin.","ur":"حضرت زینب بنت جحش رضی اللہ عنہا نبی ﷺ کے بعد سب سے پہلے وفات پانے والی زوجہ تھیں؛ وہ ہاتھ سے کام کرتیں اور صدقہ دیتی تھیں۔"}$q$::jsonb,$q$Sahih Muslim 2452$q$,$q$seerah$q$),
($q$r09$q$,$q$research$q$,$q$published$q$,$q${"en":"Who was the first teacher the Prophet ﷺ sent to Madinah to teach Islam before the Hijrah?","roman":"Hijrat se pehle Nabi ﷺ ne Islam sikhane ke liye Madinah sab se pehle kis ko bheja?","ur":"ہجرت سے پہلے نبی ﷺ نے اسلام سکھانے کے لیے مدینہ سب سے پہلے کس کو بھیجا؟"}$q$::jsonb,$q$[{"en":"Mus'ab ibn Umair (RA)","roman":"Mus'ab ibn Umair (RA)","ur":"مصعب بن عمیر رضی اللہ عنہ"},{"en":"Abdullah ibn Umm Maktum (RA)","roman":"Abdullah ibn Umm Maktum (RA)","ur":"عبداللہ بن ام مکتوم رضی اللہ عنہ"},{"en":"Mu'adh ibn Jabal (RA)","roman":"Mu'adh ibn Jabal (RA)","ur":"معاذ بن جبل رضی اللہ عنہ"},{"en":"Ammar ibn Yasir (RA)","roman":"Ammar ibn Yasir (RA)","ur":"عمار بن یاسر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"After the first Pledge of Aqabah, Mus'ab (RA) went to Yathrib, taught the Quran and many families accepted Islam.","roman":"Pehli Bait-e-Aqabah ke baad Hazrat Musab (RA) Yasrib gaye, Quran sikhaya aur bohat se gharane musalman hue.","ur":"پہلی بیعتِ عقبہ کے بعد حضرت مصعب رضی اللہ عنہ یثرب گئے، قرآن سکھایا اور بہت سے گھرانے مسلمان ہوئے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$r10$q$,$q$research$q$,$q$published$q$,$q${"en":"In whose house did the Prophet ﷺ stay when he first arrived in Madinah?","roman":"Madinah pahunch kar Nabi ﷺ pehle kis ke ghar thehre?","ur":"مدینہ پہنچ کر نبی ﷺ پہلے کس کے گھر ٹھہرے؟"}$q$::jsonb,$q$[{"en":"Abu Ayyub al-Ansari (RA)","roman":"Abu Ayyub al-Ansari (RA)","ur":"ابو ایوب انصاری رضی اللہ عنہ"},{"en":"Sa'd ibn Ubadah (RA)","roman":"Sa'd ibn Ubadah (RA)","ur":"سعد بن عبادہ رضی اللہ عنہ"},{"en":"Anas ibn Malik (RA)","roman":"Anas ibn Malik (RA)","ur":"انس بن مالک رضی اللہ عنہ"},{"en":"Ubayy ibn Ka'b (RA)","roman":"Ubayy ibn Ka'b (RA)","ur":"ابی بن کعب رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"The Prophet's ﷺ camel knelt near the house of Abu Ayyub (RA), and he hosted the Prophet ﷺ until his own rooms were built.","roman":"Nabi ﷺ ki oontni Hazrat Abu Ayyub (RA) ke ghar ke paas baith gayi, aur woh hujron ki tameer tak aap ﷺ ke mezbaan rahe.","ur":"نبی ﷺ کی اونٹنی حضرت ابو ایوب رضی اللہ عنہ کے گھر کے پاس بیٹھ گئی، اور وہ حجروں کی تعمیر تک آپ ﷺ کے میزبان رہے۔"}$q$::jsonb,$q$Ibn Hisham; Sahih Muslim 2053$q$,$q$seerah$q$),
($q$r11$q$,$q$research$q$,$q$published$q$,$q${"en":"Surah Abasa begins with the story of a blind companion who came seeking guidance. Who was he?","roman":"Surah Abasa ek nabeena sahabi ke waqiye se shuru hoti hai jo hidayat ke liye aaye. Woh kaun the?","ur":"سورۃ عبس ایک نابینا صحابی کے واقعے سے شروع ہوتی ہے جو ہدایت کے لیے آئے۔ وہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Abdullah ibn Umm Maktum (RA)","roman":"Abdullah ibn Umm Maktum (RA)","ur":"عبداللہ بن ام مکتوم رضی اللہ عنہ"},{"en":"Bilal ibn Rabah (RA)","roman":"Bilal ibn Rabah (RA)","ur":"بلال بن رباح رضی اللہ عنہ"},{"en":"Salman al-Farisi (RA)","roman":"Salman al-Farisi (RA)","ur":"سلمان فارسی رضی اللہ عنہ"},{"en":"Abu Dharr (RA)","roman":"Abu Dharr (RA)","ur":"ابو ذر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Abdullah ibn Umm Maktum (RA) was blind; he later served as a muezzin alongside Bilal (RA).","roman":"Hazrat Abdullah bin Umm-e-Maktoom (RA) nabeena the; baad mein Hazrat Bilal (RA) ke saath muazzin bhi rahe.","ur":"حضرت عبداللہ بن ام مکتوم رضی اللہ عنہ نابینا تھے؛ بعد میں حضرت بلال رضی اللہ عنہ کے ساتھ مؤذن بھی رہے۔"}$q$::jsonb,$q$Quran 80:1–10; Sunan at-Tirmidhi 3331$q$,$q$quran$q$),
($q$r12$q$,$q$research$q$,$q$published$q$,$q${"en":"Which cousin of the Prophet ﷺ, martyred at Mu'tah, was given the name \"the one with two wings\" (At-Tayyar)?","roman":"Nabi ﷺ ke kis chachazad bhai ko, jo Mutah mein shaheed hue, \"Tayyar\" (do paron wale) kaha gaya?","ur":"نبی ﷺ کے کس چچا زاد بھائی کو، جو موتہ میں شہید ہوئے، \"طیار\" (دو پروں والے) کہا گیا؟"}$q$::jsonb,$q$[{"en":"Ja'far ibn Abi Talib (RA)","roman":"Ja'far ibn Abi Talib (RA)","ur":"جعفر بن ابی طالب رضی اللہ عنہ"},{"en":"Zaid ibn Harithah (RA)","roman":"Zaid ibn Harithah (RA)","ur":"زید بن حارثہ رضی اللہ عنہ"},{"en":"Abdullah ibn Rawahah (RA)","roman":"Abdullah ibn Rawahah (RA)","ur":"عبداللہ بن رواحہ رضی اللہ عنہ"},{"en":"Aqil ibn Abi Talib (RA)","roman":"Aqil ibn Abi Talib (RA)","ur":"عقیل بن ابی طالب رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ja'far (RA) lost both arms holding the banner at Mu'tah; the Prophet ﷺ said Allah gave him two wings in Paradise.","roman":"Hazrat Jafar (RA) ke dono baazu Mutah mein jhanda thame hue kat gaye; Nabi ﷺ ne farmaya Allah ne unhein Jannat mein do par diye.","ur":"حضرت جعفر رضی اللہ عنہ کے دونوں بازو موتہ میں جھنڈا تھامے ہوئے کٹ گئے؛ نبی ﷺ نے فرمایا اللہ نے انہیں جنت میں دو پر دیے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3709$q$,$q$seerah$q$),
($q$r13$q$,$q$research$q$,$q$published$q$,$q${"en":"Who spoke for the Muslims before the Negus (An-Najashi) of Abyssinia and recited from Surah Maryam?","roman":"Habsha ke badshah Najashi ke saamne Musalmanon ki taraf se kis ne baat ki aur Surah Maryam parhi?","ur":"حبشہ کے بادشاہ نجاشی کے سامنے مسلمانوں کی طرف سے کس نے بات کی اور سورۃ مریم پڑھی؟"}$q$::jsonb,$q$[{"en":"Ja'far ibn Abi Talib (RA)","roman":"Ja'far ibn Abi Talib (RA)","ur":"جعفر بن ابی طالب رضی اللہ عنہ"},{"en":"Uthman ibn Affan (RA)","roman":"Uthman ibn Affan (RA)","ur":"عثمان بن عفان رضی اللہ عنہ"},{"en":"Abdullah ibn Mas'ud (RA)","roman":"Abdullah ibn Mas'ud (RA)","ur":"عبداللہ بن مسعود رضی اللہ عنہ"},{"en":"Zubair (RA)","roman":"Zubair (RA)","ur":"زبیر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ja'far (RA) explained Islam to the Negus and recited the opening of Surah Maryam; the Negus wept and protected the Muslims.","roman":"Hazrat Jafar (RA) ne Najashi ko Islam samjhaya aur Surah Maryam ki ibtidai ayat parhin; Najashi ro pare aur Musalmanon ko panah di.","ur":"حضرت جعفر رضی اللہ عنہ نے نجاشی کو اسلام سمجھایا اور سورۃ مریم کی ابتدائی آیات پڑھیں؛ نجاشی رو پڑے اور مسلمانوں کو پناہ دی۔"}$q$::jsonb,$q$Musnad Ahmad 1740; Ibn Hisham$q$,$q$seerah$q$),
($q$r14$q$,$q$research$q$,$q$published$q$,$q${"en":"Who looked after the Prophet ﷺ as a child, later married Zaid ibn Harithah (RA) and was the mother of Usamah (RA)?","roman":"Kaun thin jinhon ne bachpan mein Nabi ﷺ ki dekhbhal ki, baad mein Hazrat Zaid bin Haritha (RA) se nikah kiya aur Hazrat Usamah (RA) ki walida thin?","ur":"کون تھیں جنہوں نے بچپن میں نبی ﷺ کی دیکھ بھال کی، بعد میں حضرت زید بن حارثہ رضی اللہ عنہ سے نکاح کیا اور حضرت اسامہ رضی اللہ عنہ کی والدہ تھیں؟"}$q$::jsonb,$q$[{"en":"Umm Ayman (Barakah) (RA)","roman":"Umm Ayman (Barakah) (RA)","ur":"ام ایمن (برکہ) رضی اللہ عنہا"},{"en":"Halimah as-Sa'diyyah (RA)","roman":"Halimah as-Sa'diyyah (RA)","ur":"حلیمہ سعدیہ رضی اللہ عنہا"},{"en":"Fatimah bint Asad (RA)","roman":"Fatimah bint Asad (RA)","ur":"فاطمہ بنت اسد رضی اللہ عنہا"},{"en":"Thuwaybah","roman":"Thuwaybah","ur":"ثویبہ"}]$q$::jsonb,0,$q${"en":"Barakah, known as Umm Ayman (RA), cared for him after his mother's death and remained close to his family all her life.","roman":"Hazrat Barakah, jo Umm-e-Ayman (RA) kehlati hain, walida ki wafat ke baad aap ﷺ ki dekhbhal karti rahin aur umr bhar ghar ke qareeb rahin.","ur":"حضرت برکہ، جو ام ایمن رضی اللہ عنہا کہلاتی ہیں، والدہ کی وفات کے بعد آپ ﷺ کی دیکھ بھال کرتی رہیں اور عمر بھر گھرانے کے قریب رہیں۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$r15$q$,$q$research$q$,$q$published$q$,$q${"en":"For which young companion did the Prophet ﷺ pray: \"O Allah, teach him the Book\"? He became known as the interpreter of the Quran.","roman":"Kis kam umr sahabi ke liye Nabi ﷺ ne dua ki: \"Aye Allah, isay Kitab ka ilm de\"? Woh Tarjuman-ul-Quran kehlaye.","ur":"کس کم عمر صحابی کے لیے نبی ﷺ نے دعا کی: \"اے اللہ، اسے کتاب کا علم دے\"؟ وہ ترجمان القرآن کہلائے۔"}$q$::jsonb,$q$[{"en":"Abdullah ibn Abbas (RA)","roman":"Abdullah ibn Abbas (RA)","ur":"عبداللہ بن عباس رضی اللہ عنہ"},{"en":"Anas ibn Malik (RA)","roman":"Anas ibn Malik (RA)","ur":"انس بن مالک رضی اللہ عنہ"},{"en":"Abdullah ibn Umar (RA)","roman":"Abdullah ibn Umar (RA)","ur":"عبداللہ بن عمر رضی اللہ عنہ"},{"en":"Usamah ibn Zaid (RA)","roman":"Usamah ibn Zaid (RA)","ur":"اسامہ بن زید رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ibn Abbas (RA) was a boy when the Prophet ﷺ made this dua; he became one of the greatest scholars of tafseer.","roman":"Jab Nabi ﷺ ne yeh dua ki to Hazrat Ibn Abbas (RA) bachche the; baad mein tafseer ke sab se bare ulama mein se hue.","ur":"جب نبی ﷺ نے یہ دعا کی تو حضرت ابن عباس رضی اللہ عنہ بچے تھے؛ بعد میں تفسیر کے سب سے بڑے علماء میں سے ہوئے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3756$q$,$q$seerah$q$),
($q$r16$q$,$q$research$q$,$q$published$q$,$q${"en":"In which battle was the Prophet ﷺ wounded in the face and a tooth broken?","roman":"Kis jung mein Nabi ﷺ ka chehra mubarak zakhmi hua aur daant mubarak shaheed hua?","ur":"کس جنگ میں نبی ﷺ کا چہرۂ مبارک زخمی ہوا اور دندانِ مبارک شہید ہوا؟"}$q$::jsonb,$q$[{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Badr","roman":"Badr","ur":"بدر"},{"en":"Hunayn","roman":"Hunayn","ur":"حنین"},{"en":"Khaybar","roman":"Khaybar","ur":"خیبر"}]$q$::jsonb,0,$q${"en":"At Uhud the Prophet ﷺ was struck in the face and his tooth was broken; he said: \"How can a people succeed who wound their prophet?\"","roman":"Uhud mein Nabi ﷺ ke chehre par zarb lagi aur daant mubarak toota; aap ne farmaya: \"Woh qaum kaise kamyab hogi jis ne apne nabi ko zakhmi kiya?\"","ur":"احد میں نبی ﷺ کے چہرے پر ضرب لگی اور دانت مبارک ٹوٹا؛ آپ نے فرمایا: \"وہ قوم کیسے کامیاب ہوگی جس نے اپنے نبی کو زخمی کیا؟\""}$q$::jsonb,$q$Sahih Muslim 1791$q$,$q$seerah$q$),
($q$r17$q$,$q$research$q$,$q$published$q$,$q${"en":"The Prophet's ﷺ kunyah \"Abul-Qasim\" comes from the name of whom?","roman":"Nabi ﷺ ki kunniyat \"Abul-Qasim\" kis ke naam se hai?","ur":"نبی ﷺ کی کنیت \"ابو القاسم\" کس کے نام سے ہے؟"}$q$::jsonb,$q$[{"en":"His son Qasim","roman":"His son Qasim","ur":"آپ کے صاحبزادے قاسم"},{"en":"His grandfather","roman":"His grandfather","ur":"آپ کے دادا"},{"en":"His uncle Abu Talib","roman":"His uncle Abu Talib","ur":"آپ کے چچا ابو طالب"},{"en":"A companion named Qasim","roman":"A companion named Qasim","ur":"قاسم نام کے ایک صحابی"}]$q$::jsonb,0,$q${"en":"Qasim was the Prophet's ﷺ son from Khadijah (RA); he died in early childhood.","roman":"Qasim Hazrat Khadijah (RA) se Nabi ﷺ ke sahibzade the; bachpan hi mein wafat pa gaye.","ur":"قاسم حضرت خدیجہ رضی اللہ عنہا سے نبی ﷺ کے صاحبزادے تھے؛ بچپن ہی میں وفات پا گئے۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$r18$q$,$q$research$q$,$q$published$q$,$q${"en":"When the Prophet ﷺ asked for charity, which companion brought all his wealth, saying he had left Allah and His Messenger for his family?","roman":"Jab Nabi ﷺ ne sadqe ka hukm diya to kis sahabi ne apna saara maal pesh kar diya aur kaha ke ghar walon ke liye Allah aur us ka Rasool chhor aaya hoon?","ur":"جب نبی ﷺ نے صدقے کا حکم دیا تو کس صحابی نے اپنا سارا مال پیش کر دیا اور کہا کہ گھر والوں کے لیے اللہ اور اس کا رسول چھوڑ آیا ہوں؟"}$q$::jsonb,$q$[{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Umar (RA)","roman":"Umar (RA)","ur":"عمر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Abdur-Rahman ibn Awf (RA)","roman":"Abdur-Rahman ibn Awf (RA)","ur":"عبدالرحمٰن بن عوف رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Umar (RA) brought half of his wealth hoping to surpass Abu Bakr (RA), who brought everything (Sunan Abi Dawud 1678, Tirmidhi 3675).","roman":"Hazrat Umar (RA) aadha maal laaye ke Abu Bakr (RA) se aage barh jayein, magar Hazrat Abu Bakr (RA) sab kuch le aaye (Abu Dawud 1678, Tirmizi 3675).","ur":"حضرت عمر رضی اللہ عنہ آدھا مال لائے کہ ابو بکر رضی اللہ عنہ سے آگے بڑھ جائیں، مگر حضرت ابو بکر رضی اللہ عنہ سب کچھ لے آئے (ابو داؤد 1678، ترمذی 3675)۔"}$q$::jsonb,$q$Sunan Abi Dawud 1678; Jami at-Tirmidhi 3675$q$,$q$seerah$q$),
($q$t01$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Young believers slept in a cave for many years to protect their faith. In which surah is their story told?","roman":"Iman bachane ke liye kuch naujawan saalon ghaar mein soye rahe. Un ka qissa kis surah mein hai?","ur":"ایمان بچانے کے لیے کچھ نوجوان برسوں غار میں سوئے رہے۔ ان کا قصہ کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Kahf","roman":"Al-Kahf","ur":"الکہف"},{"en":"Maryam","roman":"Maryam","ur":"مریم"},{"en":"Yusuf","roman":"Yusuf","ur":"یوسف"},{"en":"Al-Anbiya","roman":"Al-Anbiya","ur":"الانبیاء"}]$q$::jsonb,0,$q${"en":"Surah Al-Kahf (\"The Cave\") is named after the Companions of the Cave (18:9–26).","roman":"Surah Al-Kahf (\"Ghaar\") ka naam Ashab-e-Kahf ke naam par hai (18:9–26).","ur":"سورۃ الکہف (\"غار\") کا نام اصحابِ کہف کے نام پر ہے (18:9–26)۔"}$q$::jsonb,$q$Quran 18:9–26$q$,$q$quran$q$),
($q$t02$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Musa (AS) travelled to learn from a servant of Allah who broke a boat and rebuilt a wall. Where is this journey described?","roman":"Hazrat Musa (AS) Allah ke ek bande se seekhne gaye jis ne kashti tori aur deewar banai. Yeh safar kahan bayan hua?","ur":"حضرت موسیٰ علیہ السلام اللہ کے ایک بندے سے سیکھنے گئے جس نے کشتی توڑی اور دیوار بنائی۔ یہ سفر کہاں بیان ہوا؟"}$q$::jsonb,$q$[{"en":"Surah Al-Kahf","roman":"Surah Al-Kahf","ur":"سورۃ الکہف"},{"en":"Surah Taha","roman":"Surah Taha","ur":"سورۃ طٰہٰ"},{"en":"Surah Al-Qasas","roman":"Surah Al-Qasas","ur":"سورۃ القصص"},{"en":"Surah Ash-Shu'ara","roman":"Surah Ash-Shu'ara","ur":"سورۃ الشعراء"}]$q$::jsonb,0,$q${"en":"Al-Kahf 18:60–82 tells of Musa (AS) and Al-Khidr, teaching that Allah's wisdom can lie behind what seems wrong at first.","roman":"Al-Kahf 18:60–82 mein Hazrat Musa (AS) aur Khizr ka qissa hai: jo pehle ghalat lage us ke peeche bhi Allah ki hikmat ho sakti hai.","ur":"الکہف 18:60–82 میں حضرت موسیٰ علیہ السلام اور خضر کا قصہ ہے: جو پہلے غلط لگے اس کے پیچھے بھی اللہ کی حکمت ہو سکتی ہے۔"}$q$::jsonb,$q$Quran 18:60–82$q$,$q$quran$q$),
($q$t03$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which righteous ruler built a barrier of iron and molten copper to hold back Ya'juj and Ma'juj?","roman":"Kis nek hukmaran ne loha aur pighla hua tanba laga kar Yajooj Majooj ko rokne ki deewar banai?","ur":"کس نیک حکمران نے لوہا اور پگھلا ہوا تانبا لگا کر یاجوج ماجوج کو روکنے کی دیوار بنائی؟"}$q$::jsonb,$q$[{"en":"Dhul-Qarnayn","roman":"Dhul-Qarnayn","ur":"ذوالقرنین"},{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"},{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Talut","roman":"Talut","ur":"طالوت"}]$q$::jsonb,0,$q${"en":"Al-Kahf 18:94–97: Dhul-Qarnayn built the barrier and said it was a mercy from his Lord.","roman":"Al-Kahf 18:94–97: Zul-Qarnain ne deewar banai aur kaha yeh mere Rab ki rehmat hai.","ur":"الکہف 18:94–97: ذوالقرنین نے دیوار بنائی اور کہا یہ میرے رب کی رحمت ہے۔"}$q$::jsonb,$q$Quran 18:83–98$q$,$q$quran$q$),
($q$t04$q$,$q$quranic$q$,$q$published$q$,$q${"en":"An ant warned the other ants to enter their homes so an army would not crush them. Whose army was it?","roman":"Ek cheonti ne baqi cheontiyon ko ghar mein jaane ko kaha taake lashkar unhein kuchal na de. Kis ka lashkar tha?","ur":"ایک چیونٹی نے باقی چیونٹیوں کو گھر میں جانے کو کہا تاکہ لشکر انہیں کچل نہ دے۔ کس کا لشکر تھا؟"}$q$::jsonb,$q$[{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"},{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Dhul-Qarnayn","roman":"Dhul-Qarnayn","ur":"ذوالقرنین"},{"en":"Talut","roman":"Talut","ur":"طالوت"}]$q$::jsonb,0,$q${"en":"Sulaiman (AS) smiled at the ant's words and thanked Allah for His favours (An-Naml 27:18–19).","roman":"Hazrat Sulaiman (AS) cheonti ki baat par muskuraye aur Allah ka shukr ada kiya (An-Naml 27:18–19).","ur":"حضرت سلیمان علیہ السلام چیونٹی کی بات پر مسکرائے اور اللہ کا شکر ادا کیا (النمل 27:18–19)۔"}$q$::jsonb,$q$Quran 27:18–19$q$,$q$quran$q$),
($q$t05$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which bird brought Sulaiman (AS) news of a queen whose people worshipped the sun?","roman":"Kis parinde ne Hazrat Sulaiman (AS) ko us malika ki khabar di jis ki qaum suraj ko poojti thi?","ur":"کس پرندے نے حضرت سلیمان علیہ السلام کو اس ملکہ کی خبر دی جس کی قوم سورج کو پوجتی تھی؟"}$q$::jsonb,$q$[{"en":"The hoopoe (hudhud)","roman":"The hoopoe (hudhud)","ur":"ہدہد"},{"en":"The crow","roman":"The crow","ur":"کوا"},{"en":"The dove","roman":"The dove","ur":"کبوتر"},{"en":"The eagle","roman":"The eagle","ur":"عقاب"}]$q$::jsonb,0,$q${"en":"The hoopoe returned from Saba with news of the queen and her people (27:20–26).","roman":"Hudhud Saba se malika aur us ki qaum ki khabar laya (27:20–26).","ur":"ہدہد سبا سے ملکہ اور اس کی قوم کی خبر لایا (27:20–26)۔"}$q$::jsonb,$q$Quran 27:20–26$q$,$q$quran$q$),
($q$t06$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"Do not associate anything with Allah… establish prayer… do not walk arrogantly.\" Who gave this advice to his son?","roman":"\"Allah ke saath kisi ko shareek na karna… namaz qaim karna… akad kar na chalna.\" Yeh nasihat kis ne apne bete ko ki?","ur":"\"اللہ کے ساتھ کسی کو شریک نہ کرنا… نماز قائم کرنا… اکڑ کر نہ چلنا۔\" یہ نصیحت کس نے اپنے بیٹے کو کی؟"}$q$::jsonb,$q$[{"en":"Luqman","roman":"Luqman","ur":"لقمان"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Ya'qub (AS)","roman":"Ya'qub (AS)","ur":"یعقوب علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"}]$q$::jsonb,0,$q${"en":"Surah Luqman 31:12–19 records the wise Luqman's advice to his son.","roman":"Surah Luqman 31:12–19 mein Hazrat Luqman ki apne bete ko nasihatein hain.","ur":"سورۃ لقمان 31:12–19 میں حضرت لقمان کی اپنے بیٹے کو نصیحتیں ہیں۔"}$q$::jsonb,$q$Quran 31:12–19$q$,$q$quran$q$),
($q$t07$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Believers were thrown into a burning trench only because they believed in Allah. Which surah mentions these \"People of the Ditch\"?","roman":"Momineen ko sirf Allah par iman lane ki wajah se aag ki khandaq mein dala gaya. \"Ashab-ul-Ukhdood\" ka zikr kis surah mein hai?","ur":"مومنین کو صرف اللہ پر ایمان لانے کی وجہ سے آگ کی خندق میں ڈالا گیا۔ \"اصحاب الاخدود\" کا ذکر کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Buruj","roman":"Al-Buruj","ur":"البروج"},{"en":"Al-Fajr","roman":"Al-Fajr","ur":"الفجر"},{"en":"At-Tariq","roman":"At-Tariq","ur":"الطارق"},{"en":"Al-Fil","roman":"Al-Fil","ur":"الفیل"}]$q$::jsonb,0,$q${"en":"Al-Buruj 85:4–8: they took revenge on the believers only because they believed in Allah, the Mighty, the Praised.","roman":"Al-Burooj 85:4–8: unhon ne momineen se sirf is liye badla liya ke woh Allah par iman laaye the.","ur":"البروج 85:4–8: انہوں نے مومنین سے صرف اس لیے بدلہ لیا کہ وہ اللہ پر ایمان لائے تھے۔"}$q$::jsonb,$q$Quran 85:4–8$q$,$q$quran$q$),
($q$t08$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Owners of a garden planned to harvest early so the poor would get nothing, and woke to find it destroyed. Which surah tells this?","roman":"Baagh ke maalikon ne subah sawere kaatne ka mansooba banaya taake ghareeb ko kuch na mile, aur baagh tabah paaya. Yeh kis surah mein hai?","ur":"باغ کے مالکوں نے صبح سویرے کاٹنے کا منصوبہ بنایا تاکہ غریب کو کچھ نہ ملے، اور باغ تباہ پایا۔ یہ کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Qalam","roman":"Al-Qalam","ur":"القلم"},{"en":"Al-Kahf","roman":"Al-Kahf","ur":"الکہف"},{"en":"Saba","roman":"Saba","ur":"سبا"},{"en":"Al-Ma'un","roman":"Al-Ma'un","ur":"الماعون"}]$q$::jsonb,0,$q${"en":"Al-Qalam 68:17–33 warns against greed and withholding the rights of the poor.","roman":"Al-Qalam 68:17–33 lalach aur ghareebon ka haq rokne se khabardar karti hai.","ur":"القلم 68:17–33 لالچ اور غریبوں کا حق روکنے سے خبردار کرتی ہے۔"}$q$::jsonb,$q$Quran 68:17–33$q$,$q$quran$q$),
($q$t09$q$,$q$quranic$q$,$q$published$q$,$q${"en":"A people with two gardens turned away from gratitude, and a great flood broke their dam. Who were they?","roman":"Do baaghon wali ek qaum shukr se mun mor gayi aur sailab ne un ka band tor diya. Woh kaun the?","ur":"دو باغوں والی ایک قوم شکر سے منہ موڑ گئی اور سیلاب نے ان کا بند توڑ دیا۔ وہ کون تھے؟"}$q$::jsonb,$q$[{"en":"The people of Saba","roman":"The people of Saba","ur":"قومِ سبا"},{"en":"The people of Aad","roman":"The people of Aad","ur":"قومِ عاد"},{"en":"The people of Lut","roman":"The people of Lut","ur":"قومِ لوط"},{"en":"Pharaoh's people","roman":"Pharaoh's people","ur":"قومِ فرعون"}]$q$::jsonb,0,$q${"en":"Surah Saba 34:15–17: \"the flood of the dam\" (sayl al-'arim) replaced their gardens.","roman":"Surah Saba 34:15–17: \"Sail-ul-Arim\" ne un ke baagh badal diye.","ur":"سورۃ سبا 34:15–17: \"سیل العرم\" نے ان کے باغ بدل دیے۔"}$q$::jsonb,$q$Quran 34:15–17$q$,$q$quran$q$),
($q$t10$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Bani Isra'il were told to slaughter a cow and kept asking questions to delay. Which surah takes its name from this story?","roman":"Bani Israel ko gaaye zibah karne ka hukm hua aur woh taalne ke liye sawal karte rahe. Kaunsi surah is qisse ke naam par hai?","ur":"بنی اسرائیل کو گائے ذبح کرنے کا حکم ہوا اور وہ ٹالنے کے لیے سوال کرتے رہے۔ کون سی سورت اس قصے کے نام پر ہے؟"}$q$::jsonb,$q$[{"en":"Al-Baqarah","roman":"Al-Baqarah","ur":"البقرہ"},{"en":"Al-An'am","roman":"Al-An'am","ur":"الانعام"},{"en":"Al-Ma'idah","roman":"Al-Ma'idah","ur":"المائدہ"},{"en":"Al-A'raf","roman":"Al-A'raf","ur":"الاعراف"}]$q$::jsonb,0,$q${"en":"Al-Baqarah means \"The Cow\"; the story is in 2:67–73.","roman":"Al-Baqarah ka matlab \"gaaye\" hai; qissa 2:67–73 mein hai.","ur":"البقرہ کا مطلب \"گائے\" ہے؛ قصہ 2:67–73 میں ہے۔"}$q$::jsonb,$q$Quran 2:67–73$q$,$q$quran$q$),
($q$t11$q$,$q$quranic$q$,$q$published$q$,$q${"en":"A small army defeated a larger one, and a young man killed their giant leader Jalut. Who was he?","roman":"Ek chhoti fauj ne bari fauj ko haraya aur ek naujawan ne un ke deo-qamat sardar Jaloot ko qatl kiya. Woh kaun the?","ur":"ایک چھوٹی فوج نے بڑی فوج کو ہرایا اور ایک نوجوان نے ان کے دیو قامت سردار جالوت کو قتل کیا۔ وہ کون تھے؟"}$q$::jsonb,$q$[{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Talut","roman":"Talut","ur":"طالوت"},{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"},{"en":"Harun (AS)","roman":"Harun (AS)","ur":"ہارون علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And Dawud killed Jalut\" (2:251): \"How many a small company has overcome a large one by permission of Allah\" (2:249).","roman":"\"Aur Dawood ne Jaloot ko qatl kiya\" (2:251): \"Kitni hi chhoti jamaatein Allah ke hukm se bari jamaaton par ghalib aayin\" (2:249).","ur":"\"اور داؤد نے جالوت کو قتل کیا\" (2:251): \"کتنی ہی چھوٹی جماعتیں اللہ کے حکم سے بڑی جماعتوں پر غالب آئیں\" (2:249)۔"}$q$::jsonb,$q$Quran 2:249–251$q$,$q$quran$q$),
($q$t12$q$,$q$quranic$q$,$q$published$q$,$q${"en":"A crow showed a man how to bury his brother. Who were the two brothers?","roman":"Ek kawwe ne ek aadmi ko apne bhai ko dafnane ka tareeqa dikhaya. Woh do bhai kaun the?","ur":"ایک کوے نے ایک آدمی کو اپنے بھائی کو دفنانے کا طریقہ دکھایا۔ وہ دو بھائی کون تھے؟"}$q$::jsonb,$q$[{"en":"The two sons of Adam (AS)","roman":"The two sons of Adam (AS)","ur":"آدم علیہ السلام کے دو بیٹے"},{"en":"Yusuf (AS) and his brother","roman":"Yusuf (AS) and his brother","ur":"یوسف علیہ السلام اور ان کا بھائی"},{"en":"Musa and Harun (AS)","roman":"Musa and Harun (AS)","ur":"موسیٰ اور ہارون علیہما السلام"},{"en":"Ismail and Ishaq (AS)","roman":"Ismail and Ishaq (AS)","ur":"اسماعیل اور اسحاق علیہما السلام"}]$q$::jsonb,0,$q${"en":"Al-Ma'idah 5:27–31 tells of the two sons of Adam; the Quran does not give their names.","roman":"Al-Maidah 5:27–31 mein Hazrat Adam (AS) ke do beton ka qissa hai; Quran un ke naam nahi batata.","ur":"المائدہ 5:27–31 میں حضرت آدم علیہ السلام کے دو بیٹوں کا قصہ ہے؛ قرآن ان کے نام نہیں بتاتا۔"}$q$::jsonb,$q$Quran 5:27–31$q$,$q$quran$q$),
($q$t13$q$,$q$quranic$q$,$q$published$q$,$q${"en":"The disciples asked Isa (AS) for a table spread with food from the sky. Which surah is named after it?","roman":"Hawariyon ne Hazrat Isa (AS) se aasman se khane ka dastarkhwan maanga. Kaunsi surah is ke naam par hai?","ur":"حواریوں نے حضرت عیسیٰ علیہ السلام سے آسمان سے کھانے کا دسترخوان مانگا۔ کون سی سورت اس کے نام پر ہے؟"}$q$::jsonb,$q$[{"en":"Al-Ma'idah","roman":"Al-Ma'idah","ur":"المائدہ"},{"en":"Al-Imran","roman":"Al-Imran","ur":"آل عمران"},{"en":"Maryam","roman":"Maryam","ur":"مریم"},{"en":"As-Saff","roman":"As-Saff","ur":"الصف"}]$q$::jsonb,0,$q${"en":"Al-Ma'idah means \"The Table Spread\" (5:112–115).","roman":"Al-Maidah ka matlab \"dastarkhwan\" hai (5:112–115).","ur":"المائدہ کا مطلب \"دسترخوان\" ہے (5:112–115)۔"}$q$::jsonb,$q$Quran 5:112–115$q$,$q$quran$q$),
($q$t14$q$,$q$quranic$q$,$q$published$q$,$q${"en":"The Quran compares those who take protectors other than Allah to a creature whose house is the weakest of houses. Which creature?","roman":"Quran Allah ke siwa sarparast banane walon ko us makhlooq se tashbeeh deta hai jis ka ghar sab se kamzor hai. Kaunsi makhlooq?","ur":"قرآن اللہ کے سوا سرپرست بنانے والوں کو اس مخلوق سے تشبیہ دیتا ہے جس کا گھر سب سے کمزور ہے۔ کون سی مخلوق؟"}$q$::jsonb,$q$[{"en":"The spider","roman":"The spider","ur":"مکڑی"},{"en":"The ant","roman":"The ant","ur":"چیونٹی"},{"en":"The bee","roman":"The bee","ur":"شہد کی مکھی"},{"en":"The fly","roman":"The fly","ur":"مکھی"}]$q$::jsonb,0,$q${"en":"\"The weakest of houses is the house of the spider\" (Al-Ankabut 29:41); the surah is named \"The Spider\".","roman":"\"Sab gharon se kamzor makri ka ghar hai\" (Al-Ankaboot 29:41); surah ka naam bhi \"Makri\" hai.","ur":"\"سب گھروں سے کمزور مکڑی کا گھر ہے\" (العنکبوت 29:41)؛ سورت کا نام بھی \"مکڑی\" ہے۔"}$q$::jsonb,$q$Quran 29:41$q$,$q$quran$q$),
($q$t15$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which creature was \"inspired\" by Allah to make homes in mountains and trees, producing a drink with healing for people?","roman":"Allah ne kis makhlooq ko pahaaron aur darakhton mein ghar banane ka \"ilham\" kiya, jis ke pet se shifa wala mashroob nikalta hai?","ur":"اللہ نے کس مخلوق کو پہاڑوں اور درختوں میں گھر بنانے کا \"الہام\" کیا، جس کے پیٹ سے شفا والا مشروب نکلتا ہے؟"}$q$::jsonb,$q$[{"en":"The bee","roman":"The bee","ur":"شہد کی مکھی"},{"en":"The silkworm","roman":"The silkworm","ur":"ریشم کا کیڑا"},{"en":"The ant","roman":"The ant","ur":"چیونٹی"},{"en":"The spider","roman":"The spider","ur":"مکڑی"}]$q$::jsonb,0,$q${"en":"An-Nahl (\"The Bee\") 16:68–69: honey has healing for people.","roman":"An-Nahl (\"Shehad ki makhi\") 16:68–69: shehad mein logon ke liye shifa hai.","ur":"النحل (\"شہد کی مکھی\") 16:68–69: شہد میں لوگوں کے لیے شفا ہے۔"}$q$::jsonb,$q$Quran 16:68–69$q$,$q$quran$q$),
($q$t16$q$,$q$quranic$q$,$q$published$q$,$q${"en":"A man came running from the far end of a town urging his people to follow the messengers. He was killed and told \"Enter Paradise\". Which surah?","roman":"Ek aadmi shehar ke door kinare se daurta aaya aur qaum ko rasoolon ki pairwi ka kaha; use shaheed kiya gaya aur kaha gaya \"Jannat mein dakhil ho ja\". Kaunsi surah?","ur":"ایک آدمی شہر کے دور کنارے سے دوڑتا آیا اور قوم کو رسولوں کی پیروی کا کہا؛ اسے شہید کیا گیا اور کہا گیا \"جنت میں داخل ہو جا\"۔ کون سی سورت؟"}$q$::jsonb,$q$[{"en":"Ya-Sin","roman":"Ya-Sin","ur":"یٰسین"},{"en":"Al-Kahf","roman":"Al-Kahf","ur":"الکہف"},{"en":"Ghafir","roman":"Ghafir","ur":"غافر"},{"en":"Al-Qasas","roman":"Al-Qasas","ur":"القصص"}]$q$::jsonb,0,$q${"en":"Ya-Sin 36:20–27: the believing man wished his people knew how his Lord had forgiven and honoured him.","roman":"Ya-Seen 36:20–27: momin aadmi ne chaha ke us ki qaum jaan le ke Rab ne use kaise bakhsha aur izzat di.","ur":"یٰسین 36:20–27: مومن آدمی نے چاہا کہ اس کی قوم جان لے کہ رب نے اسے کیسے بخشا اور عزت دی۔"}$q$::jsonb,$q$Quran 36:13–27$q$,$q$quran$q$),
($q$t17$q$,$q$quranic$q$,$q$published$q$,$q${"en":"A man proud of his treasures, whose keys were heavy for strong men, was swallowed by the earth. Who was he?","roman":"Apne khazanon par magroor ek aadmi, jis ki chabiyan taqatwar mardon par bhari thin, zameen mein dhansa diya gaya. Woh kaun tha?","ur":"اپنے خزانوں پر مغرور ایک آدمی، جس کی چابیاں طاقتور مردوں پر بھاری تھیں، زمین میں دھنسا دیا گیا۔ وہ کون تھا؟"}$q$::jsonb,$q$[{"en":"Qarun","roman":"Qarun","ur":"قارون"},{"en":"Haman","roman":"Haman","ur":"ہامان"},{"en":"Pharaoh","roman":"Pharaoh","ur":"فرعون"},{"en":"Samiri","roman":"Samiri","ur":"سامری"}]$q$::jsonb,0,$q${"en":"Al-Qasas 28:76–81: Qarun said his wealth came from his own knowledge; Allah caused the earth to swallow him and his home.","roman":"Al-Qasas 28:76–81: Qaroon ne kaha maal mujhe apne ilm se mila; Allah ne use aur us ke ghar ko zameen mein dhansa diya.","ur":"القصص 28:76–81: قارون نے کہا مال مجھے اپنے علم سے ملا؛ اللہ نے اسے اور اس کے گھر کو زمین میں دھنسا دیا۔"}$q$::jsonb,$q$Quran 28:76–81$q$,$q$quran$q$),
($q$t18$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Whose mother was inspired to place her baby in a chest and cast it into the river, trusting Allah to return him?","roman":"Kis ki walida ko ilham hua ke bachche ko sandooq mein rakh kar darya mein daal de, Allah use wapas laayega?","ur":"کس کی والدہ کو الہام ہوا کہ بچے کو صندوق میں رکھ کر دریا میں ڈال دے، اللہ اسے واپس لائے گا؟"}$q$::jsonb,$q$[{"en":"Musa (AS)","roman":"Musa (AS)","ur":"موسیٰ علیہ السلام"},{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Yusuf (AS)","roman":"Yusuf (AS)","ur":"یوسف علیہ السلام"},{"en":"Yahya (AS)","roman":"Yahya (AS)","ur":"یحییٰ علیہ السلام"}]$q$::jsonb,0,$q${"en":"Al-Qasas 28:7 and 28:13: Allah returned Musa (AS) to his mother so she would be comforted.","roman":"Al-Qasas 28:7 aur 28:13: Allah ne Hazrat Musa (AS) ko un ki walida ke paas lauta diya taake un ki aankhein thandi hon.","ur":"القصص 28:7 اور 28:13: اللہ نے حضرت موسیٰ علیہ السلام کو ان کی والدہ کے پاس لوٹا دیا تاکہ ان کی آنکھیں ٹھنڈی ہوں۔"}$q$::jsonb,$q$Quran 28:7; 20:38–39$q$,$q$quran$q$),
($q$t19$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which prophet's people are the one town the Quran says believed in time and were spared the punishment?","roman":"Kis nabi ki qaum woh wahid basti hai jis ke baare mein Quran kehta hai ke waqt par iman layi aur azab tal gaya?","ur":"کس نبی کی قوم وہ واحد بستی ہے جس کے بارے میں قرآن کہتا ہے کہ وقت پر ایمان لائی اور عذاب ٹل گیا؟"}$q$::jsonb,$q$[{"en":"Yunus (AS)","roman":"Yunus (AS)","ur":"یونس علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Salih (AS)","roman":"Salih (AS)","ur":"صالح علیہ السلام"},{"en":"Lut (AS)","roman":"Lut (AS)","ur":"لوط علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"Except the people of Yunus: when they believed, We removed from them the punishment of disgrace\" (10:98).","roman":"\"Siwaye qaum-e-Yunus ke: jab woh iman laaye to hum ne un se ruswai ka azab hata diya\" (10:98).","ur":"\"سوائے قومِ یونس کے: جب وہ ایمان لائے تو ہم نے ان سے رسوائی کا عذاب ہٹا دیا\" (10:98)۔"}$q$::jsonb,$q$Quran 10:98$q$,$q$quran$q$),
($q$t20$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which prophet asked Allah to show him how He gives life to the dead, and was told to take four birds?","roman":"Kis nabi ne Allah se poocha ke Woh murdon ko kaise zinda karta hai, aur unhein chaar parinde lene ko kaha gaya?","ur":"کس نبی نے اللہ سے پوچھا کہ وہ مردوں کو کیسے زندہ کرتا ہے، اور انہیں چار پرندے لینے کو کہا گیا؟"}$q$::jsonb,$q$[{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Uzair","roman":"Uzair","ur":"عزیر"},{"en":"Isa (AS)","roman":"Isa (AS)","ur":"عیسیٰ علیہ السلام"},{"en":"Zakariya (AS)","roman":"Zakariya (AS)","ur":"زکریا علیہ السلام"}]$q$::jsonb,0,$q${"en":"Al-Baqarah 2:260: Ibrahim (AS) said he believed, but asked so that his heart would be at rest.","roman":"Al-Baqarah 2:260: Hazrat Ibrahim (AS) ne kaha main iman rakhta hoon, magar dil ke itminan ke liye poochta hoon.","ur":"البقرہ 2:260: حضرت ابراہیم علیہ السلام نے کہا میں ایمان رکھتا ہوں، مگر دل کے اطمینان کے لیے پوچھتا ہوں۔"}$q$::jsonb,$q$Quran 2:260$q$,$q$quran$q$),
($q$t21$q$,$q$quranic$q$,$q$published$q$,$q${"en":"For which prophet did Allah make iron soft, so he could make coats of armour?","roman":"Allah ne kis nabi ke liye loha naram kar diya taake woh zirahein banayein?","ur":"اللہ نے کس نبی کے لیے لوہا نرم کر دیا تاکہ وہ زرہیں بنائیں؟"}$q$::jsonb,$q$[{"en":"Dawud (AS)","roman":"Dawud (AS)","ur":"داؤد علیہ السلام"},{"en":"Sulaiman (AS)","roman":"Sulaiman (AS)","ur":"سلیمان علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Hud (AS)","roman":"Hud (AS)","ur":"ہود علیہ السلام"}]$q$::jsonb,0,$q${"en":"\"And We made iron soft for him, [saying] make full coats of armour\" (Saba 34:10–11).","roman":"\"Aur hum ne us ke liye loha naram kar diya ke poori zirahein bana\" (Saba 34:10–11).","ur":"\"اور ہم نے اس کے لیے لوہا نرم کر دیا کہ پوری زرہیں بنا\" (سبا 34:10–11)۔"}$q$::jsonb,$q$Quran 34:10–11$q$,$q$quran$q$),
($q$t22$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"So patience is most fitting\" (fa sabrun jamil). Which grieving father said this?","roman":"\"Pas sabr hi behtar hai\" (fasabrun jameel). Yeh kis ghamzada baap ne kaha?","ur":"\"پس صبر ہی بہتر ہے\" (فصبر جمیل)۔ یہ کس غمزدہ باپ نے کہا؟"}$q$::jsonb,$q$[{"en":"Ya'qub (AS)","roman":"Ya'qub (AS)","ur":"یعقوب علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Nuh (AS)","roman":"Nuh (AS)","ur":"نوح علیہ السلام"},{"en":"Zakariya (AS)","roman":"Zakariya (AS)","ur":"زکریا علیہ السلام"}]$q$::jsonb,0,$q${"en":"Ya'qub (AS) said it when his sons brought Yusuf's (AS) shirt (12:18) and again when Binyamin was held (12:83).","roman":"Hazrat Yaqoob (AS) ne yeh tab kaha jab bete Yusuf (AS) ki qameez laaye (12:18), aur phir Binyamin ke rok liye jane par (12:83).","ur":"حضرت یعقوب علیہ السلام نے یہ تب کہا جب بیٹے یوسف علیہ السلام کی قمیص لائے (12:18)، اور پھر بنیامین کے روک لیے جانے پر (12:83)۔"}$q$::jsonb,$q$Quran 12:18, 12:83$q$,$q$quran$q$),
($q$t23$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"There is no compulsion in religion.\" In which surah is this ayah?","roman":"\"Deen mein koi zabardasti nahi.\" Yeh ayat kis surah mein hai?","ur":"\"دین میں کوئی زبردستی نہیں۔\" یہ آیت کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Baqarah","roman":"Al-Baqarah","ur":"البقرہ"},{"en":"Al-Kafirun","roman":"Al-Kafirun","ur":"الکافرون"},{"en":"Yunus","roman":"Yunus","ur":"یونس"},{"en":"Al-Hujurat","roman":"Al-Hujurat","ur":"الحجرات"}]$q$::jsonb,0,$q${"en":"Al-Baqarah 2:256, the ayah right after Ayat al-Kursi.","roman":"Al-Baqarah 2:256, Ayat-ul-Kursi ke foran baad wali ayat.","ur":"البقرہ 2:256، آیت الکرسی کے فوراً بعد والی آیت۔"}$q$::jsonb,$q$Quran 2:256$q$,$q$quran$q$),
($q$t24$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"We have not sent you except as a mercy to the worlds.\" Which surah contains this description of the Prophet ﷺ?","roman":"\"Hum ne aap ko tamam jahanon ke liye rehmat bana kar bheja.\" Yeh kis surah mein hai?","ur":"\"ہم نے آپ کو تمام جہانوں کے لیے رحمت بنا کر بھیجا۔\" یہ کس سورت میں ہے؟"}$q$::jsonb,$q$[{"en":"Al-Anbiya","roman":"Al-Anbiya","ur":"الانبیاء"},{"en":"Al-Ahzab","roman":"Al-Ahzab","ur":"الاحزاب"},{"en":"Muhammad","roman":"Muhammad","ur":"محمد"},{"en":"Al-Fath","roman":"Al-Fath","ur":"الفتح"}]$q$::jsonb,0,$q${"en":"Al-Anbiya (\"The Prophets\") 21:107.","roman":"Al-Anbiya (\"Anbiya\") 21:107.","ur":"الانبیاء 21:107۔"}$q$::jsonb,$q$Quran 21:107$q$,$q$quran$q$),
($q$t25$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"I will reinforce you with a thousand angels, following one another.\" This promise came before which battle?","roman":"\"Main hazar farishton se tumhari madad karunga jo lagatar aayenge.\" Yeh wada kis jung se pehle hua?","ur":"\"میں ہزار فرشتوں سے تمہاری مدد کروں گا جو لگاتار آئیں گے۔\" یہ وعدہ کس جنگ سے پہلے ہوا؟"}$q$::jsonb,$q$[{"en":"Badr","roman":"Badr","ur":"بدر"},{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Khandaq","roman":"Khandaq","ur":"خندق"},{"en":"Tabuk","roman":"Tabuk","ur":"تبوک"}]$q$::jsonb,0,$q${"en":"Al-Anfal 8:9 was revealed about Badr; Surah Al-Anfal discusses that battle.","roman":"Al-Anfal 8:9 Badr ke baare mein nazil hui; Surah Al-Anfal isi jung ka zikr karti hai.","ur":"الانفال 8:9 بدر کے بارے میں نازل ہوئی؛ سورۃ الانفال اسی جنگ کا ذکر کرتی ہے۔"}$q$::jsonb,$q$Quran 8:9$q$,$q$quran$q$),
($q$t26$q$,$q$quranic$q$,$q$published$q$,$q${"en":"At which battle were the Muslims pleased with their large numbers, yet it did not help them at first?","roman":"Kis jung mein Musalman apni kasrat par khush hue magar shuru mein woh kaam na aayi?","ur":"کس جنگ میں مسلمان اپنی کثرت پر خوش ہوئے مگر شروع میں وہ کام نہ آئی؟"}$q$::jsonb,$q$[{"en":"Hunayn","roman":"Hunayn","ur":"حنین"},{"en":"Badr","roman":"Badr","ur":"بدر"},{"en":"Uhud","roman":"Uhud","ur":"احد"},{"en":"Mu'tah","roman":"Mu'tah","ur":"موتہ"}]$q$::jsonb,0,$q${"en":"At-Tawbah 9:25 names Hunayn: \"your great number pleased you, but it did not avail you at all\".","roman":"At-Taubah 9:25 mein Hunain ka naam hai: \"tumhari kasrat ne tumhein khush kiya magar kuch kaam na aayi\".","ur":"التوبہ 9:25 میں حنین کا نام ہے: \"تمہاری کثرت نے تمہیں خوش کیا مگر کچھ کام نہ آئی\"۔"}$q$::jsonb,$q$Quran 9:25$q$,$q$quran$q$),
($q$t27$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which surah was revealed to clear Aishah (RA) of a false accusation (the incident of ifk)?","roman":"Kaunsi surah Hazrat Aisha (RA) par jhoote ilzam (waqia-e-ifk) se un ki baraat mein nazil hui?","ur":"کون سی سورت حضرت عائشہ رضی اللہ عنہا پر جھوٹے الزام (واقعۂ افک) سے ان کی براءت میں نازل ہوئی؟"}$q$::jsonb,$q$[{"en":"An-Nur","roman":"An-Nur","ur":"النور"},{"en":"Al-Ahzab","roman":"Al-Ahzab","ur":"الاحزاب"},{"en":"At-Tahrim","roman":"At-Tahrim","ur":"التحریم"},{"en":"Al-Hujurat","roman":"Al-Hujurat","ur":"الحجرات"}]$q$::jsonb,0,$q${"en":"An-Nur 24:11–20 declared her innocence and taught believers to think well of one another.","roman":"An-Noor 24:11–20 ne un ki baraat ka elaan kiya aur momineen ko ek doosre ke baare mein achha gumaan rakhna sikhaya.","ur":"النور 24:11–20 نے ان کی براءت کا اعلان کیا اور مومنین کو ایک دوسرے کے بارے میں اچھا گمان رکھنا سکھایا۔"}$q$::jsonb,$q$Quran 24:11–20$q$,$q$quran$q$),
($q$t28$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Of which prophet does the Quran say: \"We raised him to a high station\"?","roman":"Quran kis nabi ke baare mein kehta hai: \"Hum ne use buland maqam par uthaya\"?","ur":"قرآن کس نبی کے بارے میں کہتا ہے: \"ہم نے اسے بلند مقام پر اٹھایا\"؟"}$q$::jsonb,$q$[{"en":"Idris (AS)","roman":"Idris (AS)","ur":"ادریس علیہ السلام"},{"en":"Ilyas (AS)","roman":"Ilyas (AS)","ur":"الیاس علیہ السلام"},{"en":"Hud (AS)","roman":"Hud (AS)","ur":"ہود علیہ السلام"},{"en":"Al-Yasa (AS)","roman":"Al-Yasa (AS)","ur":"الیسع علیہ السلام"}]$q$::jsonb,0,$q${"en":"Maryam 19:56–57: Idris (AS) was a man of truth and a prophet.","roman":"Maryam 19:56–57: Hazrat Idrees (AS) sachche aur nabi the.","ur":"مریم 19:56–57: حضرت ادریس علیہ السلام سچے اور نبی تھے۔"}$q$::jsonb,$q$Quran 19:56–57$q$,$q$quran$q$),
($q$t29$q$,$q$quranic$q$,$q$published$q$,$q${"en":"Which elderly prophet prayed quietly for an heir and was given good news of a son?","roman":"Kis buzurg nabi ne chupke se waaris ki dua ki aur bete ki khushkhabri di gayi?","ur":"کس بزرگ نبی نے چپکے سے وارث کی دعا کی اور بیٹے کی خوشخبری دی گئی؟"}$q$::jsonb,$q$[{"en":"Zakariya (AS)","roman":"Zakariya (AS)","ur":"زکریا علیہ السلام"},{"en":"Ibrahim (AS)","roman":"Ibrahim (AS)","ur":"ابراہیم علیہ السلام"},{"en":"Ya'qub (AS)","roman":"Ya'qub (AS)","ur":"یعقوب علیہ السلام"},{"en":"Ayyub (AS)","roman":"Ayyub (AS)","ur":"ایوب علیہ السلام"}]$q$::jsonb,0,$q${"en":"Maryam 19:2–7: Zakariya (AS) called his Lord in a private supplication and was given Yahya.","roman":"Maryam 19:2–7: Hazrat Zakariya (AS) ne chupke se Rab ko pukara aur unhein Yahya ata hue.","ur":"مریم 19:2–7: حضرت زکریا علیہ السلام نے چپکے سے رب کو پکارا اور انہیں یحییٰ عطا ہوئے۔"}$q$::jsonb,$q$Quran 19:2–7$q$,$q$quran$q$),
($q$t30$q$,$q$quranic$q$,$q$published$q$,$q${"en":"\"Allah was pleased with the believers when they pledged allegiance to you under the tree.\" Which pledge is this?","roman":"\"Allah momineen se raazi hua jab woh darakht ke neeche aap se bait kar rahe the.\" Yeh kaunsi bait hai?","ur":"\"اللہ مومنین سے راضی ہوا جب وہ درخت کے نیچے آپ سے بیعت کر رہے تھے۔\" یہ کون سی بیعت ہے؟"}$q$::jsonb,$q$[{"en":"Bay'at ar-Ridwan (at Hudaybiyyah)","roman":"Bay'at ar-Ridwan (at Hudaybiyyah)","ur":"بیعتِ رضوان (حدیبیہ میں)"},{"en":"The first Pledge of Aqabah","roman":"The first Pledge of Aqabah","ur":"پہلی بیعتِ عقبہ"},{"en":"The second Pledge of Aqabah","roman":"The second Pledge of Aqabah","ur":"دوسری بیعتِ عقبہ"},{"en":"The pledge at the Farewell Hajj","roman":"The pledge at the Farewell Hajj","ur":"حجۃ الوداع کی بیعت"}]$q$::jsonb,0,$q${"en":"Al-Fath 48:18 refers to the Pledge of Ridwan taken at Hudaybiyyah in 6 AH.","roman":"Al-Fath 48:18 6 Hijri mein Hudaibiyah par li gayi Bait-e-Rizwan ki taraf ishara hai.","ur":"الفتح 48:18 6 ہجری میں حدیبیہ پر لی گئی بیعتِ رضوان کی طرف اشارہ ہے۔"}$q$::jsonb,$q$Quran 48:18$q$,$q$quran$q$),
($q$t31$q$,$q$seerah$q$,$q$published$q$,$q${"en":"The \"Year of Sorrow\" ('Am al-Huzn) is named after the deaths of which two people?","roman":"\"Aam-ul-Huzn\" (gham ka saal) kin do hastiyon ki wafat ki wajah se kehlata hai?","ur":"\"عام الحزن\" (غم کا سال) کن دو ہستیوں کی وفات کی وجہ سے کہلاتا ہے؟"}$q$::jsonb,$q$[{"en":"Khadijah (RA) and Abu Talib","roman":"Khadijah (RA) and Abu Talib","ur":"خدیجہ رضی اللہ عنہا اور ابو طالب"},{"en":"Aminah and Abdul-Muttalib","roman":"Aminah and Abdul-Muttalib","ur":"آمنہ اور عبدالمطلب"},{"en":"Hamzah (RA) and Ja'far (RA)","roman":"Hamzah (RA) and Ja'far (RA)","ur":"حمزہ اور جعفر رضی اللہ عنہما"},{"en":"Sumayyah (RA) and Yasir (RA)","roman":"Sumayyah (RA) and Yasir (RA)","ur":"سمیہ اور یاسر رضی اللہ عنہما"}]$q$::jsonb,0,$q${"en":"In the tenth year of prophethood the Prophet ﷺ lost his wife Khadijah (RA) and his protector Abu Talib.","roman":"Nabuwwat ke dasween saal Nabi ﷺ ki zauja Hazrat Khadijah (RA) aur himayati chacha Abu Talib wafat pa gaye.","ur":"نبوت کے دسویں سال نبی ﷺ کی زوجہ حضرت خدیجہ رضی اللہ عنہا اور حمایتی چچا ابو طالب وفات پا گئے۔"}$q$::jsonb,$q$Ibn Hisham; Ar-Raheeq al-Makhtum$q$,$q$seerah$q$),
($q$t32$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"Who was the first companion to recite the Quran aloud to Quraysh near the Ka'bah, and was beaten for it?","roman":"Kaun sahabi pehle the jinhon ne Kaaba ke paas Quraish ko buland awaz se Quran sunaya aur is par maar khayi?","ur":"کون صحابی پہلے تھے جنہوں نے کعبہ کے پاس قریش کو بلند آواز سے قرآن سنایا اور اس پر مار کھائی؟"}$q$::jsonb,$q$[{"en":"Abdullah ibn Mas'ud (RA)","roman":"Abdullah ibn Mas'ud (RA)","ur":"عبداللہ بن مسعود رضی اللہ عنہ"},{"en":"Bilal (RA)","roman":"Bilal (RA)","ur":"بلال رضی اللہ عنہ"},{"en":"Mus'ab ibn Umair (RA)","roman":"Mus'ab ibn Umair (RA)","ur":"مصعب بن عمیر رضی اللہ عنہ"},{"en":"Abu Dharr (RA)","roman":"Abu Dharr (RA)","ur":"ابو ذر رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ibn Mas'ud (RA) recited Surah Ar-Rahman at the Maqam; he was struck but said he would do it again.","roman":"Hazrat Ibn Masood (RA) ne Maqam ke paas Surah Ar-Rahman parhi; maar khayi magar kaha main phir karunga.","ur":"حضرت ابن مسعود رضی اللہ عنہ نے مقام کے پاس سورۃ الرحمٰن پڑھی؛ مار کھائی مگر کہا میں پھر کروں گا۔"}$q$::jsonb,$q$Ibn Hisham$q$,$q$seerah$q$),
($q$t33$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"\"We have been honoured ever since ___ accepted Islam,\" said Ibn Mas'ud (RA). Whose Islam is meant?","roman":"Hazrat Ibn Masood (RA) ne kaha: \"Jab se ___ musalman hue hum izzat wale ho gaye.\" Kis ka Islam muraad hai?","ur":"حضرت ابن مسعود رضی اللہ عنہ نے کہا: \"جب سے ___ مسلمان ہوئے ہم عزت والے ہو گئے۔\" کس کا اسلام مراد ہے؟"}$q$::jsonb,$q$[{"en":"Umar ibn al-Khattab (RA)","roman":"Umar ibn al-Khattab (RA)","ur":"عمر بن خطاب رضی اللہ عنہ"},{"en":"Hamzah (RA)","roman":"Hamzah (RA)","ur":"حمزہ رضی اللہ عنہ"},{"en":"Abu Bakr (RA)","roman":"Abu Bakr (RA)","ur":"ابو بکر رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"After Umar (RA) accepted Islam the Muslims could pray openly at the Ka'bah.","roman":"Hazrat Umar (RA) ke Islam ke baad Musalman Kaaba mein khul kar namaz parhne lage.","ur":"حضرت عمر رضی اللہ عنہ کے اسلام کے بعد مسلمان کعبہ میں کھل کر نماز پڑھنے لگے۔"}$q$::jsonb,$q$Sahih al-Bukhari 3684$q$,$q$seerah$q$),
($q$t34$q$,$q$sahabah$q$,$q$published$q$,$q${"en":"In the brotherhood of Madinah, an Ansari offered Abdur-Rahman ibn Awf (RA) half his wealth. He replied, \"Show me the market.\" Who was that Ansari?","roman":"Madinah ki mawakhat mein ek Ansari ne Hazrat Abdur-Rahman bin Auf (RA) ko aadha maal pesh kiya. Unhon ne kaha \"mujhe bazaar dikha do\". Woh Ansari kaun the?","ur":"مدینہ کی مواخات میں ایک انصاری نے حضرت عبدالرحمٰن بن عوف رضی اللہ عنہ کو آدھا مال پیش کیا۔ انہوں نے کہا \"مجھے بازار دکھا دو\"۔ وہ انصاری کون تھے؟"}$q$::jsonb,$q$[{"en":"Sa'd ibn ar-Rabi' (RA)","roman":"Sa'd ibn ar-Rabi' (RA)","ur":"سعد بن الربیع رضی اللہ عنہ"},{"en":"Sa'd ibn Mu'adh (RA)","roman":"Sa'd ibn Mu'adh (RA)","ur":"سعد بن معاذ رضی اللہ عنہ"},{"en":"Abu Ayyub (RA)","roman":"Abu Ayyub (RA)","ur":"ابو ایوب رضی اللہ عنہ"},{"en":"Ubayy ibn Ka'b (RA)","roman":"Ubayy ibn Ka'b (RA)","ur":"ابی بن کعب رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"The Prophet ﷺ paired muhajirun with ansar; Sa'd ibn ar-Rabi' (RA) offered generously and Abdur-Rahman (RA) chose to work and trade.","roman":"Nabi ﷺ ne muhajireen aur ansar ko bhai banaya; Hazrat Saad bin Rabi (RA) ne dil khol kar pesh kiya aur Hazrat Abdur-Rahman (RA) ne mehnat aur tijarat ko chuna.","ur":"نبی ﷺ نے مہاجرین اور انصار کو بھائی بنایا؛ حضرت سعد بن ربیع رضی اللہ عنہ نے دل کھول کر پیش کیا اور حضرت عبدالرحمٰن رضی اللہ عنہ نے محنت اور تجارت کو چنا۔"}$q$::jsonb,$q$Sahih al-Bukhari 2048$q$,$q$seerah$q$),
($q$t35$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Who wrote down the Treaty of Hudaybiyyah at the Prophet's ﷺ dictation?","roman":"Sulah Hudaibiyah Nabi ﷺ ke likhwane par kis ne likhi?","ur":"صلح حدیبیہ نبی ﷺ کے لکھوانے پر کس نے لکھی؟"}$q$::jsonb,$q$[{"en":"Ali ibn Abi Talib (RA)","roman":"Ali ibn Abi Talib (RA)","ur":"علی بن ابی طالب رضی اللہ عنہ"},{"en":"Zaid ibn Thabit (RA)","roman":"Zaid ibn Thabit (RA)","ur":"زید بن ثابت رضی اللہ عنہ"},{"en":"Uthman (RA)","roman":"Uthman (RA)","ur":"عثمان رضی اللہ عنہ"},{"en":"Mu'awiyah (RA)","roman":"Mu'awiyah (RA)","ur":"معاویہ رضی اللہ عنہ"}]$q$::jsonb,0,$q${"en":"Ali (RA) wrote the treaty; Suhayl objected to the words \"Messenger of Allah\" and the Prophet ﷺ agreed to change them.","roman":"Hazrat Ali (RA) ne muahida likha; Suhail ne \"Rasoolullah\" ke alfaz par aitraaz kiya aur Nabi ﷺ ne unhein badalne par ittefaq kiya.","ur":"حضرت علی رضی اللہ عنہ نے معاہدہ لکھا؛ سہیل نے \"رسول اللہ\" کے الفاظ پر اعتراض کیا اور نبی ﷺ نے انہیں بدلنے پر اتفاق کیا۔"}$q$::jsonb,$q$Sahih al-Bukhari 2699$q$,$q$seerah$q$),
($q$t36$q$,$q$seerah$q$,$q$published$q$,$q${"en":"Where did the Prophet ﷺ deliver his main sermon of the Farewell Hajj, saying the blood and property of Muslims are sacred?","roman":"Nabi ﷺ ne Hajjat-ul-Wida ka bara khutba, jis mein Musalmanon ke khoon aur maal ki hurmat bayan ki, kahan diya?","ur":"نبی ﷺ نے حجۃ الوداع کا بڑا خطبہ، جس میں مسلمانوں کے خون اور مال کی حرمت بیان کی، کہاں دیا؟"}$q$::jsonb,$q$[{"en":"At Arafah","roman":"At Arafah","ur":"عرفہ میں"},{"en":"Inside the Ka'bah","roman":"Inside the Ka'bah","ur":"کعبہ کے اندر"},{"en":"At Masjid Quba","roman":"At Masjid Quba","ur":"مسجدِ قبا میں"},{"en":"At Mount Uhud","roman":"At Mount Uhud","ur":"احد پہاڑ پر"}]$q$::jsonb,0,$q${"en":"Jabir's (RA) long hadith in Sahih Muslim describes the sermon given at Arafah (in the valley of Uranah).","roman":"Sahih Muslim mein Hazrat Jabir (RA) ki lambi hadith Arafah (Wadi Uranah) mein diye gaye khutbe ko bayan karti hai.","ur":"صحیح مسلم میں حضرت جابر رضی اللہ عنہ کی لمبی حدیث عرفہ (وادیٔ عرنہ) میں دیے گئے خطبے کو بیان کرتی ہے۔"}$q$::jsonb,$q$Sahih Muslim 1218$q$,$q$seerah$q$),
($q$t37$q$,$q$seerah$q$,$q$published$q$,$q${"en":"In whose room did the Prophet ﷺ spend his final illness and pass away?","roman":"Nabi ﷺ ne aakhri beemari kis ke hujre mein guzari aur wahin wafat payi?","ur":"نبی ﷺ نے آخری بیماری کس کے حجرے میں گزاری اور وہیں وفات پائی؟"}$q$::jsonb,$q$[{"en":"Aishah (RA)","roman":"Aishah (RA)","ur":"عائشہ رضی اللہ عنہا"},{"en":"Umm Salamah (RA)","roman":"Umm Salamah (RA)","ur":"ام سلمہ رضی اللہ عنہا"},{"en":"Hafsah (RA)","roman":"Hafsah (RA)","ur":"حفصہ رضی اللہ عنہا"},{"en":"Maymunah (RA)","roman":"Maymunah (RA)","ur":"میمونہ رضی اللہ عنہا"}]$q$::jsonb,0,$q${"en":"His wives allowed him to stay in Aishah's (RA) room, where he passed away and was buried.","roman":"Azwaj-e-Mutahharat ne ijazat di ke aap ﷺ Hazrat Aisha (RA) ke hujre mein rahein; wahin wafat payi aur dafan hue.","ur":"ازواجِ مطہرات نے اجازت دی کہ آپ ﷺ حضرت عائشہ رضی اللہ عنہا کے حجرے میں رہیں؛ وہیں وفات پائی اور دفن ہوئے۔"}$q$::jsonb,$q$Sahih al-Bukhari 4450$q$,$q$seerah$q$)
